BOOK.add({
  subject: "cg",
  id: "cg-19",
  title: "छत्तीसगढ़ — त्योहार, मेले-मड़ई, धार्मिक स्थल, संत एवं पंथ (विस्तृत अभ्यास)",
  notes: "\n<h3>1. कृषि-चक्र पर आधारित त्योहार-कैलेंडर (माह ↔ तिथि ↔ पर्व)</h3>\n<p>छत्तीसगढ़ के अधिकांश लोक-पर्व धान की खेती के चक्र से जुड़े हैं — बोआई (आषाढ़) से लेकर कटाई-मिंजाई (अगहन-पूस) और अन्नदान (छेरछेरा) तक। इसलिए हरेली को \"पहला त्योहार\" और छेरछेरा को फसल-उत्सव का समापन माना जाता है।</p>\n<table>\n<tr><th>हिंदू माह</th><th>तिथि</th><th>पर्व</th><th>मुख्य परंपरा</th></tr>\n<tr><td>चैत्र</td><td>कृष्ण एकादशी (पापमोचनी)</td><td>माता कर्मा जयंती</td><td>साहू (तेली) समाज की आराध्य भक्त माता कर्मा</td></tr>\n<tr><td>चैत्र</td><td>शुक्ल प्रतिपदा–नवमी</td><td>चैत्र नवरात्रि</td><td>जंवारा (जोत-जंवारा) बोना, जस गीत, डोंगरगढ़-रतनपुर में मेले</td></tr>\n<tr><td>चैत्र</td><td>चैत्र माह</td><td>सरहुल (उरांव), माटी तिहार (बस्तर)</td><td>साल फूलने पर सरना में पूजा; बीज बोने से पूर्व धरती की पूजा</td></tr>\n<tr><td>वैशाख</td><td>कृष्ण एकादशी</td><td>वल्लभाचार्य जयंती</td><td>चंपारण (रायपुर) में मेला</td></tr>\n<tr><td>वैशाख</td><td>शुक्ल तृतीया</td><td>अक्ती (अक्षय तृतीया)</td><td>पुतरा-पुतरी विवाह, नए कृषि वर्ष का आरंभ, बीज का दोना ठाकुर देव को</td></tr>\n<tr><td>ज्येष्ठ</td><td>शुक्ल दशमी</td><td>गंगा दशहरा</td><td>सरगुजा-कोरिया अंचल में मेले, दशहरा गीत</td></tr>\n<tr><td>आषाढ़</td><td>शुक्ल द्वितीया</td><td>रथयात्रा / गोंचा (जगदलपुर)</td><td>तुपकी से पेंग चलाना; 360 घर आरण्यक ब्राह्मण समाज द्वारा आयोजन</td></tr>\n<tr><td>आषाढ़</td><td>प्रथम दिवस</td><td>रामगढ़ महोत्सव (सरगुजा)</td><td>कालिदास के मेघदूत की स्मृति (\"आषाढस्य प्रथम दिवसे\")</td></tr>\n<tr><td>श्रावण</td><td>अमावस्या</td><td>हरेली</td><td>कृषि औजार पूजा, गेंड़ी, बैगा द्वारा नीम की डाल, लोहार द्वारा दरवाज़े पर कील, पशुओं को औषधीय जड़ी</td></tr>\n<tr><td>श्रावण</td><td>शुक्ल पंचमी</td><td>नागपंचमी</td><td>नाग पूजा, कुश्ती (दंगल)</td></tr>\n<tr><td>श्रावण</td><td>शुक्ल पक्ष (बोआई) → पूर्णिमा के अगले दिन विसर्जन</td><td>भोजली</td><td>गेहूँ के अंकुर, \"देवी गंगा, देवी गंगा, लहर तुरंगा\", भोजली बदकर मितानी</td></tr>\n<tr><td>भाद्रपद</td><td>कृष्ण षष्ठी</td><td>कमरछठ (हलषष्ठी)</td><td>बलराम (हलधर) जयंती; पसहर चावल, भैंस का दूध-दही, छह प्रकार की भाजी, सगरी</td></tr>\n<tr><td>भाद्रपद</td><td>कृष्ण अष्टमी</td><td>आठे कन्हैया (जन्माष्टमी)</td><td>दीवार पर आठ पुतलियों/कृष्ण के चित्र बनाकर पूजा</td></tr>\n<tr><td>भाद्रपद</td><td>अमावस्या</td><td>पोला (पोरा)</td><td>बैल पूजा, नंदिया बइला, ठेठरी-खुरमी, गेंड़ी विसर्जन</td></tr>\n<tr><td>भाद्रपद</td><td>शुक्ल तृतीया</td><td>तीजा (हरितालिका)</td><td>मायके आना, करू भात, निर्जला व्रत, अगली सुबह फरहार</td></tr>\n<tr><td>भाद्रपद</td><td>शुक्ल पंचमी (ओड़िशा-सीमावर्ती अंचल)</td><td>नवाखाई / नुआखाई</td><td>नई फसल का अन्न पहले इष्टदेव को, फिर परिवार ग्रहण करता है</td></tr>\n<tr><td>भाद्रपद</td><td>शुक्ल एकादशी</td><td>करमा</td><td>करम वृक्ष की डाल, करमसेनी देवी, करमा-धरमा कथा, करमा नृत्य</td></tr>\n<tr><td>भाद्रपद</td><td>भादो माह (शनिवार)</td><td>भंगाराम जात्रा (केशकाल)</td><td>देवी-देवताओं की \"अदालत\", दोषी देवों को दंड</td></tr>\n<tr><td>आश्विन</td><td>पितृ पक्ष → नवरात्रि → दशमी</td><td>पितर, क्वार नवरात्रि, दशहरा</td><td>बस्तर दशहरा का चरम; ज्योति कलश</td></tr>\n<tr><td>कार्तिक</td><td>अमावस्या (सुरहुत्ती)</td><td>देवारी (दीपावली), गौरा-गौरी</td><td>सुआ नृत्य, ईसर देव (शिव)-गौरा विवाह, सोंटा</td></tr>\n<tr><td>कार्तिक</td><td>शुक्ल प्रतिपदा</td><td>गोवर्धन पूजा</td><td>गोबर का गोवर्धन, पशुओं को खिचड़ी, राउत गायों को सोहई बाँधते हैं</td></tr>\n<tr><td>कार्तिक</td><td>दीपावली के बाद</td><td>मातर</td><td>राउत (यादव) समाज, खोड़हर देव, मड़ई</td></tr>\n<tr><td>कार्तिक</td><td>शुक्ल एकादशी</td><td>जेठौनी (देवउठनी)</td><td>तुलसी विवाह, गन्ने का मंडप, राउत नाचा आरंभ</td></tr>\n<tr><td>कार्तिक</td><td>पूर्णिमा</td><td>कार्तिक पुन्नी</td><td>महादेव घाट (रायपुर, खारुन तट) मेला</td></tr>\n<tr><td>अगहन</td><td>प्रत्येक गुरुवार</td><td>अगहन बिरस्पत</td><td>स्त्रियों द्वारा लक्ष्मी पूजा का व्रत</td></tr>\n<tr><td>पौष</td><td>पूर्णिमा</td><td>छेरछेरा (पूस पुन्नी)</td><td>अन्नदान, \"छेरछेरा, कोठी के धान ल हेरहेरा\"; तुरतुरिया मेला</td></tr>\n<tr><td>पौष</td><td>शुक्ल एकादशी–त्रयोदशी</td><td>रामनामी बड़े भजन मेला</td><td>महानदी तटीय गाँवों में बारी-बारी से</td></tr>\n<tr><td>माघ</td><td>पूर्णिमा</td><td>माघी पुन्नी</td><td>राजिम, शिवरीनारायण, सिरपुर, रतनपुर, दामाखेड़ा, कुदुरमाल मेले</td></tr>\n<tr><td>माघ (सत्यापित करें)</td><td>तिथि की पुष्टि नहीं</td><td>गहिरा गुरु मेला</td><td>गहिरा गाँव (रायगढ़)</td></tr>\n<tr><td>फाल्गुन</td><td>शुक्ल पंचमी–सप्तमी</td><td>गिरौदपुरी मेला</td><td>जैतखाम पर सफेद झंडा चढ़ाना</td></tr>\n<tr><td>फाल्गुन</td><td>फागुन माह</td><td>दंतेवाड़ा फागुन मड़ई; होली (फाग)</td><td>देवी दंतेश्वरी की पालकी; नगाड़े के साथ फाग</td></tr>\n</table>\n<div class=\"tip\">ट्रिक — \"सावन में हरियाली, भादो में बैल-बहन, कार्तिक में गाय-ग्वाला, पूस में दान\": हरेली (श्रावण) → पोला-तीजा (भाद्रपद) → गोवर्धन-मातर (कार्तिक) → छेरछेरा (पौष)।</div>\n\n<h3>2. देवारी (दीपावली) का पंचपर्व — छत्तीसगढ़ी रूप</h3>\n<table>\n<tr><th>दिन</th><th>छत्तीसगढ़ी नाम/रूप</th><th>विशेषता</th></tr>\n<tr><td>कार्तिक कृष्ण त्रयोदशी</td><td>धनतेरस</td><td>बर्तन-खरीदी, यम दीया</td></tr>\n<tr><td>कृष्ण चतुर्दशी</td><td>नरक चौदस</td><td>प्रातः स्नान, दीपदान</td></tr>\n<tr><td>अमावस्या</td><td>सुरहुत्ती (बड़ी देवारी)</td><td>लक्ष्मी पूजा; रात में गोंड समाज की गौरा-गौरी पूजा (ईसर राजा-गौरा का विवाह); गौरा गीत</td></tr>\n<tr><td>शुक्ल प्रतिपदा</td><td>गोवर्धन पूजा</td><td>गोबर का गोवर्धन; पशुओं को खिचड़ी; राउत मोरपंख-पलाश की \"सोहई\" गायों के गले में बाँधते हैं, दोहे पारते हैं</td></tr>\n<tr><td>इसके बाद</td><td>मातर / भाई दूज</td><td>राउत समाज का मातर (खोड़हर देव, मड़ई), बहनों के घर भाई दूज</td></tr>\n</table>\n<p><b>सुआ नृत्य</b> दीपावली से पहले शुरू होकर गौरा-गौरी विवाह के साथ समाप्त होता है। <b>दियारी</b> बस्तर के जनजातीय समाज का दीपावली-रूप है, जिसमें पशुधन की पूजा, गाय-बैलों को खिचड़ी खिलाना और नई फसल का उत्सव प्रमुख है; यह प्रायः गाँव-गाँव अलग-अलग दिनों में मनाया जाता है।</p>\n\n<h3>3. जनजातीय पर्व</h3>\n<table>\n<tr><th>पर्व</th><th>समुदाय/क्षेत्र</th><th>मुख्य तथ्य</th></tr>\n<tr><td>सरहुल</td><td>उरांव (जशपुर-सरगुजा)</td><td>चैत्र माह; साल वृक्ष के फूल; सूर्य-धरती विवाह का प्रतीक; पुजारी \"पाहन\"; पूजा-स्थल \"सरना\"</td></tr>\n<tr><td>करमा</td><td>उरांव, गोंड, बैगा, कंवर आदि</td><td>भाद्रपद शुक्ल एकादशी; करम डाल आँगन में गाड़कर पूजा; करमा-धरमा भाइयों की कथा</td></tr>\n<tr><td>माटी तिहार</td><td>बस्तर</td><td>चैत्र; बीज बोने से पहले धरती माता की पूजा; इस दिन भूमि नहीं खोदी जाती</td></tr>\n<tr><td>नवाखानी</td><td>बस्तर व पूर्वी छत्तीसगढ़</td><td>नई फसल का पहला अन्न देवी-देवताओं/पूर्वजों को अर्पित कर ग्रहण करना</td></tr>\n<tr><td>दियारी</td><td>बस्तर</td><td>पशुधन व फसल का उत्सव (दीपावली का जनजातीय रूप)</td></tr>\n<tr><td>गोंचा</td><td>जगदलपुर (बस्तर)</td><td>जगन्नाथ रथयात्रा; तुपकी (बाँस की नली) से पेंग (मालकांगनी) फल चलाकर भगवान को सलामी</td></tr>\n<tr><td>भंगाराम जात्रा</td><td>केशकाल (कोंडागांव)</td><td>भादो माह; भंगाराम देवी के दरबार में नौ परगनों के देवी-देवताओं की पेशी; दोषी देव को \"दंड\" (निर्वासन)</td></tr>\n<tr><td>ककसार</td><td>मुरिया (बस्तर)</td><td>लिंगो पेन की आराधना से जुड़ा पर्व-नृत्य</td></tr>\n</table>\n\n<h3>4. बस्तर दशहरा — रस्में क्रम से (कुल लगभग 75 दिन)</h3>\n<table>\n<tr><th>क्रम</th><th>रस्म</th><th>समय</th><th>विवरण</th></tr>\n<tr><td>1</td><td>पाट जात्रा</td><td>श्रावण (हरेली) अमावस्या</td><td>दंतेश्वरी मंदिर के सामने बिलौरी गाँव से लाई साल की लकड़ी \"ठुरलू खोटला\" की पूजा; रथ-निर्माण के औजारों की पूजा</td></tr>\n<tr><td>2</td><td>डेरी गड़ाई</td><td>भाद्रपद</td><td>सिरासार भवन में साल की दो डेरी (खंभे) गाड़कर रथ-निर्माण की औपचारिक शुरुआत</td></tr>\n<tr><td>3</td><td>काछन गादी</td><td>आश्विन अमावस्या</td><td>पनका जाति की कुंवारी कन्या (काछन देवी) काँटों के झूले पर बैठकर पर्व की \"अनुमति\" देती है</td></tr>\n<tr><td>4</td><td>कलश स्थापना व जोगी बिठाई</td><td>आश्विन शुक्ल प्रतिपदा</td><td>सिरासार भवन में हल्बा जाति का व्यक्ति 9 दिन गड्ढे में योगासन में बैठता है</td></tr>\n<tr><td>5</td><td>रथ परिक्रमा (फूल रथ)</td><td>द्वितीया से सप्तमी</td><td>चार पहियों वाला फूल रथ प्रतिदिन परिक्रमा करता है</td></tr>\n<tr><td>6</td><td>बेल पूजा</td><td>नवरात्रि के मध्य</td><td>सरगीपाल गाँव में जुड़वाँ बेल फल की पूजा</td></tr>\n<tr><td>7</td><td>निशा जात्रा</td><td>अष्टमी की मध्यरात्रि</td><td>निशागुड़ी (वर्ष में एक बार खुलने वाला मंदिर) में बलि-पूजा</td></tr>\n<tr><td>8</td><td>कुंवारी पूजा, जोगी उठाई</td><td>नवमी</td><td>जोगी की तपस्या पूर्ण</td></tr>\n<tr><td>9</td><td>मावली परघाव</td><td>नवमी</td><td>दंतेवाड़ा से आई माँ दंतेश्वरी (मावली) की डोली-छत्र का राजा द्वारा स्वागत</td></tr>\n<tr><td>10</td><td>भीतर रैनी</td><td>विजयादशमी</td><td>आठ पहियों वाला विजय रथ; रात में माड़िया रथ \"चुराकर\" कुम्हड़ाकोट ले जाते हैं</td></tr>\n<tr><td>11</td><td>बाहर रैनी</td><td>एकादशी</td><td>राजा कुम्हड़ाकोट जाकर नवाखानी करते हैं, रथ वापस राजमहल लाया जाता है</td></tr>\n<tr><td>12</td><td>काछन जात्रा, मुरिया दरबार</td><td>द्वादशी-त्रयोदशी</td><td>सिरासार में मांझी-चालकी व जनप्रतिनिधियों की सभा; प्रथम मुरिया दरबार 8 मार्च 1876</td></tr>\n<tr><td>13</td><td>कुटुंब जात्रा</td><td>त्रयोदशी के आसपास</td><td>बस्तर के परगनों से आए सैकड़ों ग्राम देवी-देवताओं की ससम्मान विदाई</td></tr>\n<tr><td>14</td><td>ओहाड़ी / मावली विदाई</td><td>अंत में</td><td>माँ दंतेश्वरी की डोली की दंतेवाड़ा के लिए विदाई</td></tr>\n</table>\n<div class=\"tip\">क्रम याद रखें — \"पाट-डेरी-काछन-जोगी, फूल-बेल-निशा, मावली-भीतर-बाहर, दरबार-कुटुंब-ओहाड़ी\"।</div>\n<ul>\n<li>बस्तर दशहरा में रावण-दहन नहीं होता; यह देवी दंतेश्वरी की आराधना का पर्व है और इसे विश्व का सबसे लंबी अवधि वाला दशहरा कहा जाता है।</li>\n<li>रथ परंपरा महाराजा पुरुषोत्तम देव (15वीं सदी) की जगन्नाथ पुरी यात्रा व \"रथपति\" उपाधि से जोड़ी जाती है। मान्यता है कि मूल 12 पहियों का रथ चलाने में कठिनाई के कारण उसे 4 पहियों (फूल रथ) और 8 पहियों (विजय रथ) में बाँटा गया।</li>\n<li>रथ का निर्माण परंपरागत रूप से बेड़ाउमरगाँव और झारउमरगाँव के ग्रामीण कारीगर करते हैं।</li>\n</ul>\n\n<h3>5. गोंचा पर्व (जगदलपुर)</h3>\n<ul>\n<li>आषाढ़ शुक्ल द्वितीया को जगन्नाथ, बलभद्र व सुभद्रा की रथयात्रा; आयोजन 360 घर आरण्यक ब्राह्मण समाज करता है।</li>\n<li>क्रम: चंदन जात्रा (देव-स्नान) → अनसर काल → नेत्रोत्सव → गोंचा रथयात्रा → हेरा पंचमी → बाहुड़ा गोंचा (वापसी) → देवशयनी एकादशी।</li>\n<li>\"गोंचा\" नाम बाँस की नली \"तुपकी\" और \"पेंग\" फल से होने वाली सलामी के लिए प्रसिद्ध; परंपरा पुरुषोत्तम देव की पुरी यात्रा से जुड़ी है।</li>\n</ul>\n\n<h3>6. प्रमुख मेले — स्थान ↔ अवसर</h3>\n<table>\n<tr><th>मेला</th><th>जिला</th><th>अवसर/तिथि</th><th>विशेषता</th></tr>\n<tr><td>राजिम माघी पुन्नी मेला (2024 से \"राजिम कुंभ कल्प\")</td><td>गरियाबंद</td><td>माघ पूर्णिमा–महाशिवरात्रि</td><td>महानदी-पैरी-सोंढूर संगम; राजीव लोचन, कुलेश्वर महादेव; पंचकोसी यात्रा</td></tr>\n<tr><td>शिवरीनारायण</td><td>जांजगीर-चांपा</td><td>माघ पूर्णिमा से</td><td>नर-नारायण मंदिर; शबरी प्रसंग; \"छत्तीसगढ़ की जगन्नाथपुरी\"</td></tr>\n<tr><td>सिरपुर</td><td>महासमुंद</td><td>माघ पूर्णिमा; सिरपुर महोत्सव</td><td>लक्ष्मण मंदिर, गंधेश्वर महादेव, बौद्ध विहार</td></tr>\n<tr><td>रतनपुर</td><td>बिलासपुर</td><td>माघ पूर्णिमा; दोनों नवरात्रि</td><td>महामाया मंदिर; हज़ारों ज्योति कलश</td></tr>\n<tr><td>दामाखेड़ा</td><td>बलौदाबाजार-भाटापारा</td><td>माघ पूर्णिमा (संत समागम)</td><td>कबीरपंथ की प्रमुख गद्दी</td></tr>\n<tr><td>कुदुरमाल</td><td>कोरबा (हसदेव तट)</td><td>माघ पूर्णिमा</td><td>कबीरपंथी गुरुओं की समाधियाँ</td></tr>\n<tr><td>गिरौदपुरी</td><td>बलौदाबाजार-भाटापारा</td><td>फाल्गुन शुक्ल 5–7</td><td>गुरु घासीदास जन्मस्थली; 77 मीटर जैतखाम</td></tr>\n<tr><td>चंपारण</td><td>रायपुर</td><td>वैशाख कृष्ण एकादशी</td><td>वल्लभाचार्य प्राकट्य स्थल; चंपकेश्वर महादेव</td></tr>\n<tr><td>तुरतुरिया</td><td>बलौदाबाजार-भाटापारा</td><td>पौष पूर्णिमा</td><td>वाल्मीकि आश्रम; लव-कुश जन्म की मान्यता; बौद्ध भिक्षुणी विहार के अवशेष</td></tr>\n<tr><td>महादेव घाट</td><td>रायपुर</td><td>कार्तिक पूर्णिमा</td><td>खारुन तट; हटकेश्वर महादेव</td></tr>\n<tr><td>पीथमपुर</td><td>जांजगीर-चांपा</td><td>होली के बाद (धूल पंचमी)</td><td>कलेश्वरनाथ; नागा साधुओं की \"शिवजी की बारात\"</td></tr>\n<tr><td>भोरमदेव महोत्सव</td><td>कबीरधाम</td><td>चैत्र कृष्ण त्रयोदशी के आसपास</td><td>\"छत्तीसगढ़ का खजुराहो\"</td></tr>\n<tr><td>नारायणपुर मड़ई</td><td>नारायणपुर</td><td>फरवरी</td><td>अबूझमाड़ का प्रमुख मड़ई</td></tr>\n<tr><td>दंतेवाड़ा फागुन मड़ई</td><td>दंतेवाड़ा</td><td>फाल्गुन</td><td>लगभग 10 दिन; आखेट-परंपरा की रस्में</td></tr>\n<tr><td>भंगाराम जात्रा</td><td>कोंडागांव (केशकाल)</td><td>भादो</td><td>देवताओं की अदालत</td></tr>\n<tr><td>झलमला</td><td>बालोद</td><td>चैत्र व क्वार नवरात्रि</td><td>गंगा मैया मंदिर</td></tr>\n<tr><td>खल्लारी</td><td>महासमुंद</td><td>चैत्र पूर्णिमा</td><td>खल्लारी माता; भीम-हिडिंबा कथा</td></tr>\n<tr><td>रामनामी बड़े भजन मेला</td><td>महानदी तटीय गाँव (बारी-बारी)</td><td>पौष शुक्ल 11–13</td><td>राम-नाम का सामूहिक भजन</td></tr>\n<tr><td>गहिरा गुरु मेला</td><td>रायगढ़ (गहिरा गाँव)</td><td>तिथि की पुष्टि नहीं (स्थानीय स्रोत देखें)</td><td>सनातन संत समाज</td></tr>\n<tr><td>मदकू द्वीप मेला</td><td>शिवनाथ नदी का द्वीप</td><td>फरवरी</td><td>सौ वर्ष से अधिक पुराना ईसाई मेला; प्राचीन शिव मंदिर-अवशेष भी</td></tr>\n<tr><td>लुतरा शरीफ उर्स</td><td>बिलासपुर (सीपत के पास)</td><td>वार्षिक उर्स</td><td>बाबा सैयद इंसान अली शाह की दरगाह</td></tr>\n</table>\n<p><b>राजिम पंचकोसी यात्रा</b> के पाँच शिव-स्थल: पटेश्वर (पटेवा), चंपकेश्वर (चंपारण), ब्रह्मनेश्वर (बम्हनी), फणिकेश्वर (फिंगेश्वर) और कर्पूरेश्वर (कोपरा)। राजिम का नाम भक्त माता <b>राजिम (राजिम तेलिन)</b> से जुड़ा माना जाता है।</p>\n\n<h3>7. शक्तिपीठ एवं देवी-स्थल</h3>\n<table>\n<tr><th>देवी</th><th>स्थान (जिला)</th><th>विशेष तथ्य</th></tr>\n<tr><td>महामाया</td><td>रतनपुर (बिलासपुर)</td><td>शक्तिपीठ (सती का स्कंध); कलचुरि रत्नदेव प्रथम से संबद्ध; महालक्ष्मी-महासरस्वती</td></tr>\n<tr><td>दंतेश्वरी</td><td>दंतेवाड़ा</td><td>शक्तिपीठ (सती का दाँत); शंखिनी-डंकिनी संगम; बस्तर राजवंश की कुलदेवी</td></tr>\n<tr><td>बम्लेश्वरी</td><td>डोंगरगढ़ (राजनांदगांव)</td><td>पहाड़ी पर बड़ी, नीचे छोटी बम्लेश्वरी; राजा वीरसेन व कामकंदला-माधवनल कथा; रोपवे</td></tr>\n<tr><td>चंद्रहासिनी</td><td>चंद्रपुर</td><td>महानदी-मांड संगम</td></tr>\n<tr><td>महामाया</td><td>अंबिकापुर (सरगुजा)</td><td>नगर का नाम देवी अंबिका से</td></tr>\n<tr><td>कुदरगढ़ी (बागेश्वरी)</td><td>कुदरगढ़ (सूरजपुर)</td><td>पहाड़ी मंदिर; रामनवमी मेला</td></tr>\n<tr><td>खल्लारी माता</td><td>खल्लारी (महासमुंद)</td><td>भीम चूल्हा, हिडिंबा कथा</td></tr>\n<tr><td>चंडी माता</td><td>घुंचापाली, बागबाहरा (महासमुंद)</td><td>आरती के समय भालुओं का आना</td></tr>\n<tr><td>बिलाई माता (विंध्यवासिनी)</td><td>धमतरी</td><td>नवरात्रि ज्योति कलश</td></tr>\n<tr><td>अंगारमोती</td><td>गंगरेल (धमतरी)</td><td>डूब के बाद गंगरेल बाँध के पास पुनर्स्थापित</td></tr>\n<tr><td>गंगा मैया</td><td>झलमला (बालोद)</td><td>तालाब से प्राप्त प्रतिमा की कथा</td></tr>\n<tr><td>सर्वमंगला, मड़वारानी</td><td>कोरबा</td><td>हसदेव अंचल</td></tr>\n</table>\n\n<h3>8. शिव, विष्णु एवं राम से जुड़े स्थल</h3>\n<ul>\n<li><b>खरौद</b> (जांजगीर-चांपा) — लक्ष्मणेश्वर महादेव, \"लक्षलिंग\" (एक लाख छिद्र); \"छत्तीसगढ़ की काशी\"।</li>\n<li><b>भोरमदेव</b> (कबीरधाम) — फणिनागवंशी गोपालदेव के काल (1089 ई.) का शिव मंदिर; पास में मड़वा महल (विवाह-स्मारक) और छेरकी महल।</li>\n<li><b>हटकेश्वर महादेव</b> (रायपुर, महादेव घाट) — खारुन नदी तट; कार्तिक पुन्नी मेला।</li>\n<li><b>देवबलौदा</b> (दुर्ग) — कलचुरि कालीन शिव मंदिर; महाशिवरात्रि मेला।</li>\n<li><b>चंदखुरी</b> (रायपुर) — जलसेन तालाब के मध्य माता कौशल्या मंदिर; कौशल्या की जन्मभूमि मानी जाती है।</li>\n<li><b>सिहावा</b> (धमतरी) — शृंगी ऋषि आश्रम; महानदी उद्गम; सप्त ऋषियों के आश्रम।</li>\n<li><b>राम वन गमन पथ</b> — प्रथम चरण के स्थल: सीतामढ़ी-हरचौका (प्रवेश स्थल), रामगढ़, शिवरीनारायण, तुरतुरिया, चंदखुरी, राजिम, सिहावा, जगदलपुर, रामाराम (सुकमा)।</li>\n<li><b>दूधाधारी मठ</b> (रायपुर) — महंत बलभद्र दास द्वारा स्थापित; केवल दूध पर रहने के कारण \"दूधाधारी\" नाम; रामानंदी वैष्णव परंपरा।</li>\n</ul>\n\n<h3>9. संत एवं पंथ</h3>\n<h4>(क) गुरु घासीदास व सतनाम पंथ</h4>\n<ul>\n<li>जन्म 18 दिसंबर 1756, गिरौदपुरी; पिता महंगू दास, माता अमरौतिन; पत्नी सफुरा माता; पुत्र गुरु बालकदास व अमरदास।</li>\n<li>छाता पहाड़ पर औंरा-धौंरा वृक्ष के नीचे तपस्या; गिरौदपुरी में चरण कुंड, अमृत कुंड।</li>\n<li>संदेश: \"मनखे-मनखे एक समान\"। प्रतीक: जैतखाम (सफेद ध्वज वाला स्तंभ — सत्य व शांति)।</li>\n<li><b>सात सिद्धांत:</b> (1) सतनाम पर विश्वास (2) मूर्ति पूजा का निषेध (3) जाति-भेद का विरोध (4) जीव हत्या (हिंसा) का निषेध (5) मांस-मदिरा व नशे का निषेध (6) पर-स्त्री को माता मानना / व्यभिचार निषेध (7) दोपहर में हल न चलाना (पशु पर दया)।</li>\n<li>सतनामी तीर्थ: गिरौदपुरी, भंडारपुरी (गुरुद्वारा), तेलासी, चटुआपुरी, खडुआपुरी।</li>\n<li>स्मृति: गुरु घासीदास विश्वविद्यालय बिलासपुर (1983; 2009 से केंद्रीय विश्वविद्यालय), गुरु घासीदास राष्ट्रीय उद्यान, गुरु घासीदास सम्मान। ध्यान दें — रायपुर का \"महंत घासीदास संग्रहालय\" (1875) नांदगांव के राजा महंत घासीदास के नाम पर है, गुरु घासीदास के नहीं।</li>\n</ul>\n<h4>(ख) कबीरपंथ</h4>\n<ul>\n<li>कबीर के प्रमुख शिष्य <b>धनी धर्मदास</b> (बांधवगढ़ के वैश्य) ने छत्तीसगढ़ में धर्मदासी शाखा फैलाई; वे छत्तीसगढ़ी के आदि कवि माने जाते हैं।</li>\n<li>उनके पुत्र मुक्तामणि (चूड़ामणि) नाम साहब से वंश-गुरु परंपरा चली; कबीर द्वारा \"42 वंश\" तक गद्दी का आशीर्वाद मान्य है।</li>\n<li>गद्दी कवर्धा सहित कई स्थानों से होकर दामाखेड़ा (बलौदाबाजार-भाटापारा, सिमगा के पास) पहुँची; कुदुरमाल (कोरबा) में गुरुओं की समाधियाँ।</li>\n<li>प्रतीक: सफेद वस्त्र, कंठी, \"चौका आरती\", सत्यनाम।</li>\n</ul>\n<h4>(ग) रामनामी संप्रदाय</h4>\n<ul>\n<li>संस्थापक: परशुराम भारद्वाज, चारपारा गाँव (मालखरौदा क्षेत्र); 1890 के दशक में।</li>\n<li>शरीर पर \"राम-राम\" का गोदना (पूरे शरीर पर गोदना वाले \"नखशिख\"), मोरपंख का मुकुट, राम-नाम छपी ओढ़नी; मूर्ति पूजा नहीं, रामचरितमानस का पाठ।</li>\n<li>बड़े भजन मेला: पौष शुक्ल एकादशी से त्रयोदशी, महानदी तट के गाँवों में बारी-बारी।</li>\n</ul>\n<h4>(घ) वल्लभाचार्य</h4>\n<ul>\n<li>जन्म 1479 ई., वैशाख कृष्ण एकादशी, चंपारण (चंपारण्य) रायपुर; पिता लक्ष्मण भट्ट, माता इल्लमागारु (तेलुगु ब्राह्मण परिवार)।</li>\n<li>दर्शन: शुद्धाद्वैत; भक्ति-मार्ग: पुष्टिमार्ग; \"महाप्रभु\" कहलाते हैं; चंपारण में प्राकट्य बैठक — गुजरात-राजस्थान के वैष्णव तीर्थयात्री बड़ी संख्या में आते हैं।</li>\n</ul>\n<h4>(ङ) अन्य संत</h4>\n<ul>\n<li><b>संत गहिरा गुरु</b> (रामेश्वर गहिरा गुरु) — जन्म गहिरा गाँव (रायगढ़); 1943 में \"सनातन धर्म संत समाज\"; जनजातियों में नशामुक्ति व स्वच्छता; अंबिकापुर का सरगुजा विश्वविद्यालय अब \"संत गहिरा गुरु विश्वविद्यालय\"।</li>\n<li><b>माता कर्मा</b> — भक्त, साहू समाज की आराध्य; जयंती चैत्र कृष्ण एकादशी।</li>\n<li><b>स्वामी विवेकानंद</b> — किशोरावस्था (1877–79) में लगभग दो वर्ष रायपुर में रहे; बूढ़ा तालाब अब \"विवेकानंद सरोवर\"।</li>\n<li><b>आचार्य विद्यासागर</b> — दिगंबर जैन आचार्य; 18 फरवरी 2024 को चंद्रगिरि तीर्थ (डोंगरगढ़) में समाधि।</li>\n</ul>\n\n<h3>10. बौद्ध, जैन, ईसाई एवं मुस्लिम स्थल</h3>\n<table>\n<tr><th>धर्म</th><th>स्थल</th><th>तथ्य</th></tr>\n<tr><td>बौद्ध</td><td>सिरपुर</td><td>आनंदप्रभु कुटी विहार (महाशिवगुप्त बालार्जुन काल), स्वस्तिक विहार; ह्वेनसांग की यात्रा (639 ई.)</td></tr>\n<tr><td>बौद्ध</td><td>मैनपाट (सरगुजा)</td><td>1962-63 से तिब्बती शरणार्थी बस्ती; \"मिनी तिब्बत\", बौद्ध मठ</td></tr>\n<tr><td>बौद्ध</td><td>डोंगरगढ़ — प्रज्ञागिरि</td><td>पहाड़ी पर विशाल बुद्ध प्रतिमा</td></tr>\n<tr><td>बौद्ध</td><td>मल्हार, तुरतुरिया</td><td>बौद्ध अवशेष; तुरतुरिया में भिक्षुणी विहार</td></tr>\n<tr><td>जैन</td><td>आरंग</td><td>भांड देवल (11वीं सदी) — तीन तीर्थंकर प्रतिमाएँ</td></tr>\n<tr><td>जैन</td><td>नगपुरा (दुर्ग)</td><td>श्री उवसग्गहरं पार्श्व तीर्थ, शिवनाथ तट</td></tr>\n<tr><td>जैन</td><td>चंद्रगिरि (डोंगरगढ़)</td><td>आचार्य विद्यासागर समाधि स्थल</td></tr>\n<tr><td>ईसाई</td><td>कुनकुरी (जशपुर)</td><td>\"रोज़री की महारानी\" महागिरजाघर — एशिया का दूसरा सबसे बड़ा चर्च; नींव 1962 (बिशप स्टैनिसलॉस तिग्गा), लोकार्पण 27 अक्टूबर 1979</td></tr>\n<tr><td>ईसाई</td><td>बिश्रामपुर</td><td>1868 में रेव. ऑस्कर लोर द्वारा छत्तीसगढ़ का प्रथम मिशन</td></tr>\n<tr><td>ईसाई</td><td>मदकू द्वीप</td><td>फरवरी का ईसाई मेला</td></tr>\n<tr><td>इस्लाम</td><td>लुतरा शरीफ</td><td>बाबा सैयद इंसान अली शाह की दरगाह, उर्स</td></tr>\n</table>\n\n<h3>11. राजकीय अवकाश एवं प्रतीक दिवस</h3>\n<table>\n<tr><th>तिथि</th><th>दिवस</th><th>संदर्भ</th></tr>\n<tr><td>1 नवंबर</td><td>राज्य स्थापना दिवस (राज्योत्सव)</td><td>2000 में राज्य गठन; राज्य अलंकरण सम्मान</td></tr>\n<tr><td>18 दिसंबर</td><td>गुरु घासीदास जयंती</td><td>सामान्य अवकाश; पंथी नृत्य</td></tr>\n<tr><td>10 दिसंबर</td><td>शहीद वीर नारायण सिंह बलिदान दिवस</td><td>1857, रायपुर (जयस्तंभ चौक)</td></tr>\n<tr><td>10 फरवरी</td><td>भूमकाल स्मृति दिवस</td><td>1910 का भूमकाल विद्रोह (गुंडाधुर)</td></tr>\n<tr><td>9 अगस्त</td><td>विश्व आदिवासी दिवस</td><td>2019 से राज्य में सामान्य अवकाश</td></tr>\n<tr><td>28 नवंबर</td><td>छत्तीसगढ़ी राजभाषा दिवस</td><td>2007 के विधेयक की स्मृति</td></tr>\n<tr><td>1 मई</td><td>बोरे-बासी दिवस (श्रमिक दिवस)</td><td>श्रम का सम्मान</td></tr>\n<tr><td>21 दिसंबर</td><td>पं. सुंदरलाल शर्मा जयंती</td><td>छत्तीसगढ़ के गांधी</td></tr>\n<tr><td>चैत्र कृष्ण एकादशी</td><td>माता कर्मा जयंती</td><td>साहू समाज</td></tr>\n</table>\n",
  extra: "\n<h3>गहन तथ्य — जो सामान्य पाठक नहीं जानता</h3>\n<h4>भ्रम पैदा करने वाले जोड़े</h4>\n<table>\n<tr><th>भ्रम</th><th>सही तथ्य</th></tr>\n<tr><td>गुरु घासीदास बनाम महंत घासीदास</td><td>गुरु घासीदास = सतनाम पंथ के प्रवर्तक (1756); महंत घासीदास = नांदगांव के राजा, जिनके नाम पर रायपुर संग्रहालय (1875)</td></tr>\n<tr><td>भोजली बनाम जंवारा</td><td>भोजली = श्रावण में गेहूँ के अंकुर (मित्रता बदना); जंवारा = नवरात्रि में बोए जाने वाले अंकुर (देवी सेवा)</td></tr>\n<tr><td>मातर बनाम मड़ई</td><td>मातर = राउत समाज का दीपावली-पश्चात पर्व; मड़ई = देवी-देवताओं के साथ लगने वाला क्षेत्रीय मेला (बस्तर में मुख्यतः माघ-फाल्गुन)</td></tr>\n<tr><td>गौरा-गौरी बनाम तीजा</td><td>दोनों में शिव-पार्वती; पर गौरा-गौरी दीपावली की रात (गोंड समाज) और तीजा भाद्रपद शुक्ल तृतीया (स्त्रियों का व्रत)</td></tr>\n<tr><td>कमरछठ बनाम छठ पूजा</td><td>कमरछठ = भाद्रपद कृष्ण षष्ठी, बलराम-जयंती, संतान हेतु; छठ पूजा = कार्तिक शुक्ल षष्ठी, सूर्य उपासना</td></tr>\n<tr><td>दामाखेड़ा बनाम कुदुरमाल</td><td>दोनों कबीरपंथी; दामाखेड़ा = वर्तमान प्रमुख गद्दी (बलौदाबाजार-भाटापारा), कुदुरमाल = कोरबा में हसदेव तट पर गुरु-समाधियाँ</td></tr>\n<tr><td>गिरौदपुरी बनाम भंडारपुरी</td><td>गिरौदपुरी = जन्मस्थली व जैतखाम; भंडारपुरी = गुरुद्वारा/गुरु-गद्दी का स्थल</td></tr>\n<tr><td>भीतर रैनी बनाम बाहर रैनी</td><td>भीतर रैनी (दशमी) = रथ \"चोरी\" होकर कुम्हड़ाकोट; बाहर रैनी (एकादशी) = राजा द्वारा नवाखानी कर रथ वापस लाना</td></tr>\n<tr><td>फूल रथ बनाम विजय रथ</td><td>फूल रथ 4 पहिए (द्वितीया–सप्तमी), विजय रथ 8 पहिए (दशमी-एकादशी)</td></tr>\n</table>\n<h4>\"पुन्नी\" (पूर्णिमा) याद रखने की तालिका</h4>\n<ul>\n<li><b>कार्तिक पुन्नी</b> — महादेव घाट रायपुर।</li>\n<li><b>पूस पुन्नी</b> — छेरछेरा, तुरतुरिया।</li>\n<li><b>माघी पुन्नी</b> — राजिम, शिवरीनारायण, सिरपुर, रतनपुर, दामाखेड़ा, कुदुरमाल।</li>\n<li><b>चैत पुन्नी</b> — खल्लारी।</li>\n</ul>\n<h4>छेरछेरा की लोककथा</h4>\n<p>लोकमान्यता के अनुसार रतनपुर के कलचुरि राजा कल्याण साय लगभग आठ वर्ष मुगल दरबार में रहकर लौटे तो रानी फुलकैना ने प्रसन्न होकर प्रजा में अन्न-धन बँटवाया; तभी से पौष पूर्णिमा पर दान की परंपरा चली। बच्चे-युवा टोलियों में \"छेरछेरा, कोठी के धान ल हेरहेरा\" और \"अरन बरन कोदो दरन, जभे देबे तभे टरन\" कहते हुए अन्न माँगते हैं; डंडा नाच (शैला) होता है।</p>\n<h4>मितानी (मित्रता) बदने की परंपराएँ</h4>\n<p>भोजली, जंवारा, महाप्रसाद (जगन्नाथ का प्रसाद), गंगाजल, दौनापान — इन्हें साक्षी बनाकर आजीवन मित्रता का संबंध जोड़ा जाता है; ऐसे मित्र एक-दूसरे का नाम नहीं लेते, बल्कि \"भोजली\", \"महापरसाद\" आदि कहकर पुकारते हैं।</p>\n<h4>तिथि-ट्रिक</h4>\n<ul>\n<li>तीन \"एकादशी\": चैत्र कृष्ण 11 = कर्मा जयंती; वैशाख कृष्ण 11 = वल्लभ जयंती; भाद्रपद शुक्ल 11 = करमा; कार्तिक शुक्ल 11 = जेठौनी; पौष शुक्ल 11 = रामनामी भजन मेला।</li>\n<li>तीन \"अमावस्या\": श्रावण = हरेली (पाट जात्रा भी); भाद्रपद = पोला; आश्विन = काछन गादी; कार्तिक = सुरहुत्ती (गौरा-गौरी)।</li>\n<li>दो \"तृतीया\": वैशाख शुक्ल 3 = अक्ती; भाद्रपद शुक्ल 3 = तीजा।</li>\n<li>\"षष्ठी\": भाद्रपद कृष्ण 6 = कमरछठ (बलराम); कार्तिक शुक्ल 6 = छठ पूजा।</li>\n</ul>\n<h4>संख्या-तथ्य</h4>\n<ul>\n<li>बस्तर दशहरा ≈ 75 दिन; विजय रथ 8 पहिए, फूल रथ 4 पहिए।</li>\n<li>गिरौदपुरी जैतखाम ≈ 77 मीटर (कुतुब मीनार ≈ 72.5 मीटर से ऊँचा)।</li>\n<li>प्रथम मुरिया दरबार — 8 मार्च 1876।</li>\n<li>गोंचा का आयोजक — 360 घर आरण्यक ब्राह्मण समाज।</li>\n<li>राजिम पंचकोसी — 5 शिव धाम; कबीरपंथ — 42 वंश का आशीर्वाद; सतनाम — 7 सिद्धांत।</li>\n<li>कुनकुरी महागिरजाघर — 1962 नींव, 1979 लोकार्पण; बिश्रामपुर मिशन — 1868।</li>\n</ul>\n",
  questions: [
    {"q":"हरेली के दिन घरों के मुख्य दरवाज़े पर लोहे की कील ठोकने की परंपरा परंपरागत रूप से कौन निभाता है?","o":["राउत","लोहार","बैगा","कुम्हार"],"a":1,"e":"हरेली पर लोहार दरवाज़ों की चौखट पर कील ठोकता है और बैगा नीम की डाल लगाता है — दोनों को अनिष्ट से रक्षा का प्रतीक माना जाता है।"},
    {"q":"कमरछठ (हलषष्ठी) किस देवता के जन्मोत्सव के रूप में मनाई जाती है?","o":["श्रीकृष्ण","कार्तिकेय","बलराम","गणेश"],"a":2,"e":"भाद्रपद कृष्ण षष्ठी हलधर बलराम की जयंती है; इसीलिए इस दिन हल से जोते खेत का अन्न (सामान्य चावल) वर्जित रहता है और पसहर चावल खाया जाता है।"},
    {"q":"कमरछठ व्रत में परंपरागत रूप से किस पशु का दूध-दही उपयोग किया जाता है?","o":["गाय","बकरी","भेड़","भैंस"],"a":3,"e":"कमरछठ में गाय के दूध के बजाय भैंस का दूध, दही व घी प्रयोग होता है; साथ में छह प्रकार की भाजी बनाई जाती है।"},
    {"q":"छत्तीसगढ़ी परंपरा में \"आठे कन्हैया\" किस पर्व से संबंधित है?","o":["जन्माष्टमी","राम नवमी","दुर्गाष्टमी","शीतला अष्टमी"],"a":0,"e":"भाद्रपद कृष्ण अष्टमी (जन्माष्टमी) पर दीवार पर आठ पुतलियों/कृष्ण का चित्र बनाकर \"आठे कन्हैया\" की पूजा होती है।"},
    {"q":"छत्तीसगढ़ में दीपावली (लक्ष्मी पूजा) की रात को किस नाम से पुकारा जाता है?","o":["जेठौनी","सुरहुत्ती","मातर","दियारी"],"a":1,"e":"कार्तिक अमावस्या की दीपावली रात \"सुरहुत्ती\" कहलाती है; इसी रात गोंड समाज गौरा-गौरी पूजा करता है।"},
    {"q":"गोवर्धन पूजा पर राउत समाज द्वारा गायों के गले में बाँधी जाने वाली मोरपंख व पलाश आदि से बनी माला को क्या कहते हैं?","o":["हमेल","सूता","सोहई","कंठी"],"a":2,"e":"राउत अपने मालिकों की गायों को \"सोहई\" बाँधते हैं और बदले में अन्न-वस्त्र पाते हैं; हमेल व सूता स्त्रियों के गले के आभूषण हैं।"},
    {"q":"गौरा-गौरी पूजा में \"ईसर देव\" किस देवता का रूप माने जाते हैं?","o":["विष्णु","सूर्य","इंद्र","शिव"],"a":3,"e":"गौरा-गौरी पूजा ईसर देव (शिव) और गौरा (पार्वती) के विवाह का उत्सव है, जो सुरहुत्ती की रात गोंड समाज मनाता है।"},
    {"q":"अगहन (मार्गशीर्ष) माह के प्रत्येक गुरुवार को स्त्रियों द्वारा रखा जाने वाला लक्ष्मी-व्रत छत्तीसगढ़ में किस नाम से प्रसिद्ध है?","o":["अगहन बिरस्पत","पूस पुन्नी","कातिक नहान","माघी पुन्नी"],"a":0,"e":"अगहन बिरस्पत (गुरुवार) पर घरों को लीपकर चावल-आटे के चौक बनाकर लक्ष्मी पूजा होती है।"},
    {"q":"नागपंचमी के अवसर पर छत्तीसगढ़ के गाँवों में परंपरागत रूप से कौन-सा खेल आयोजित किया जाता है?","o":["गेंड़ी दौड़","कुश्ती (दंगल)","फुगड़ी","भौंरा"],"a":1,"e":"श्रावण शुक्ल पंचमी (नागपंचमी) को नाग पूजा के साथ अखाड़ों में कुश्ती-दंगल की परंपरा है।"},
    {"q":"भोजली विसर्जन के समय गाया जाने वाला प्रसिद्ध लोकगीत किस पंक्ति से आरंभ होता है?","o":["तरी हरी नाना","अरपा पैरी के धार","देवी गंगा, देवी गंगा, लहर तुरंगा","मोर संग चलव रे"],"a":2,"e":"भोजली गीत \"देवी गंगा, देवी गंगा, लहर तुरंगा...\" गाते हुए भोजली को जल में सिराया जाता है; \"तरी हरी नाना\" सुआ गीत की टेक है।"},
    {"q":"छेरछेरा पर्व पर दान माँगते समय बोली जाने वाली प्रसिद्ध पंक्ति कौन-सी है?","o":["अररर भैया","हरियर हरियर","जय गंगान","छेरछेरा, कोठी के धान ल हेरहेरा"],"a":3,"e":"टोलियाँ \"छेरछेरा, कोठी के धान ल हेरहेरा\" कहकर कोठी (भंडार) से धान निकालकर दान देने का आग्रह करती हैं।"},
    {"q":"लोकमान्यता के अनुसार छेरछेरा पर्व की शुरुआत रतनपुर के किस राजा के मुगल दरबार से लौटने की खुशी में हुई?","o":["कल्याण साय","रत्नदेव प्रथम","पृथ्वीदेव","बाहर साय"],"a":0,"e":"राजा कल्याण साय के लगभग आठ वर्ष बाद लौटने पर रानी फुलकैना ने प्रजा में अन्न-धन बँटवाया — यही पौष पूर्णिमा के दान का आधार माना जाता है।"},
    {"q":"जगदलपुर के गोंचा पर्व का पारंपरिक आयोजक समाज कौन-सा है?","o":["हल्बा समाज","360 घर आरण्यक ब्राह्मण समाज","मुरिया समाज","पनका समाज"],"a":1,"e":"गोंचा (जगन्नाथ रथयात्रा) का आयोजन 360 घर आरण्यक ब्राह्मण समाज करता है; बस्तर दशहरे की काछन देवी पनका जाति से होती है।"},
    {"q":"गोंचा पर्व की किस रस्म में भगवान जगन्नाथ के नेत्रों का अनुष्ठान होता है, जो रथयात्रा से ठीक पहले होती है?","o":["चंदन जात्रा","हेरा पंचमी","नेत्रोत्सव","बाहुड़ा गोंचा"],"a":2,"e":"स्नान (चंदन जात्रा) के बाद अनसर काल और फिर नेत्रोत्सव होता है; इसके बाद गोंचा रथयात्रा निकलती है।"},
    {"q":"गोंचा पर्व में भगवान जगन्नाथ की वापसी (लौटती) रथयात्रा को क्या कहा जाता है?","o":["चंदन जात्रा","नेत्रोत्सव","हेरा पंचमी","बाहुड़ा गोंचा"],"a":3,"e":"वापसी की यात्रा \"बाहुड़ा गोंचा\" कहलाती है; पर्व का समापन देवशयनी एकादशी पर होता है।"},
    {"q":"बस्तर दशहरा की पाट जात्रा में पूजी जाने वाली साल की लकड़ी को क्या कहा जाता है?","o":["ठुरलू खोटला","डेरी","आंगा","डांग"],"a":0,"e":"बिलौरी गाँव से लाई साल की लकड़ी \"ठुरलू खोटला\" की पूजा से पाट जात्रा होती है; डेरी बाद में डेरी गड़ाई रस्म में गाड़ी जाती है।"},
    {"q":"बस्तर दशहरा में \"डेरी गड़ाई\" रस्म कहाँ संपन्न होती है?","o":["कुम्हड़ाकोट","सिरासार भवन","निशागुड़ी","दंतेवाड़ा"],"a":1,"e":"सिरासार भवन में साल की दो डेरियाँ गाड़कर रथ-निर्माण औपचारिक रूप से आरंभ होता है; जोगी बिठाई और मुरिया दरबार भी यहीं होते हैं।"},
    {"q":"बस्तर दशहरा में काछन देवी के रूप में काँटों के झूले पर बैठने वाली कन्या किस जाति की होती है?","o":["हल्बा","माड़िया","पनका","भतरा"],"a":2,"e":"काछन गादी (आश्विन अमावस्या) में पनका जाति की कुंवारी कन्या पर्व की अनुमति देती है; जोगी बिठाई में हल्बा जाति का व्यक्ति बैठता है।"},
    {"q":"बस्तर दशहरा की \"जोगी बिठाई\" में 9 दिन तक तपस्या करने वाला व्यक्ति परंपरागत रूप से किस जाति का होता है?","o":["पनका","मुरिया","राउत","हल्बा"],"a":3,"e":"जोगी बिठाई में हल्बा जाति का व्यक्ति सिरासार भवन के गड्ढे में नौ दिन योगासन में बैठता है; नवमी को जोगी उठाई होती है।"},
    {"q":"बस्तर दशहरा में अष्टमी की मध्यरात्रि को होने वाली रस्म कौन-सी है?","o":["निशा जात्रा","मावली परघाव","भीतर रैनी","कुटुंब जात्रा"],"a":0,"e":"निशा जात्रा अष्टमी की आधी रात को निशागुड़ी मंदिर में होती है, जो वर्ष में केवल एक बार खुलता है।"},
    {"q":"बस्तर दशहरा में नवरात्रि की द्वितीया से सप्तमी तक प्रतिदिन परिक्रमा करने वाले \"फूल रथ\" में कितने पहिए होते हैं?","o":["दो","चार","छह","आठ"],"a":1,"e":"फूल रथ चार पहियों का होता है; दशमी-एकादशी का विजय रथ आठ पहियों का।"},
    {"q":"बस्तर दशहरा की \"बेल पूजा\" रस्म किस गाँव में संपन्न होती है?","o":["बिलौरी","कुम्हड़ाकोट","सरगीपाल","किलेपाल"],"a":2,"e":"सरगीपाल गाँव में जुड़वाँ बेल फलों की पूजा होती है; बिलौरी से पाट जात्रा की लकड़ी आती है।"},
    {"q":"बस्तर दशहरा के प्रथम मुरिया दरबार का आयोजन कब हुआ था?","o":["1857","1910","1947","8 मार्च 1876"],"a":3,"e":"सिरोंचा के डिप्टी कमिश्नर मैकजॉर्ज ने 8 मार्च 1876 को मांझी-चालकियों को संबोधित किया — यही प्रथम मुरिया दरबार माना जाता है।"},
    {"q":"बस्तर दशहरा की \"बाहर रैनी\" रस्म में राजा कुम्हड़ाकोट जाकर क्या करते हैं?","o":["नवाखानी (नए अन्न का ग्रहण)","रावण दहन","जोगी उठाई","काछन देवी से अनुमति"],"a":0,"e":"एकादशी को राजा कुम्हड़ाकोट में नवाखानी कर रथ को ससम्मान राजमहल वापस लाते हैं; बस्तर दशहरे में रावण दहन नहीं होता।"},
    {"q":"बस्तर दशहरा के रथ का निर्माण परंपरागत रूप से किन गाँवों के कारीगर करते हैं?","o":["बिलौरी और सरगीपाल","बेड़ाउमरगाँव और झारउमरगाँव","किलेपाल और कुम्हड़ाकोट","आमाबाल और चित्रकोट"],"a":1,"e":"रथ-निर्माण का दायित्व बेड़ाउमरगाँव व झारउमरगाँव के ग्रामीणों का है; वे पाट जात्रा में पूजे गए औजारों से काम आरंभ करते हैं।"},
    {"q":"केशकाल (कोंडागांव) की \"भंगाराम जात्रा\" की सबसे बड़ी विशेषता क्या है?","o":["रथयात्रा","पशु मेला","देवी-देवताओं की अदालत, जिसमें दोषी देवों को दंड मिलता है","नौका दौड़"],"a":2,"e":"भादो माह की इस जात्रा में भंगाराम देवी के दरबार में ग्राम देवताओं की पेशी होती है; दोषी देव को \"दंड\" देकर निर्वासित किया जाता है।"},
    {"q":"दंतेवाड़ा की प्रसिद्ध \"फागुन मड़ई\" किस देवी से जुड़ी है?","o":["महामाया","बम्लेश्वरी","चंद्रहासिनी","दंतेश्वरी"],"a":3,"e":"फाल्गुन माह में लगभग दस दिन चलने वाली फागुन मड़ई माँ दंतेश्वरी की पालकी और आखेट-परंपरा की रस्मों के लिए प्रसिद्ध है।"},
    {"q":"राजिम के माघी पुन्नी मेले को 2024 में किस नाम से आयोजित किया गया?","o":["राजिम कुंभ कल्प","राजीव लोचन महोत्सव","त्रिवेणी उत्सव","माघ महोत्सव"],"a":0,"e":"2024 में यह मेला \"राजिम कुंभ कल्प\" नाम से 24 फरवरी से 8 मार्च 2024 (माघ पूर्णिमा से महाशिवरात्रि) तक महानदी-पैरी-सोंढूर संगम पर आयोजित हुआ।"},
    {"q":"राजिम नगर का नाम किस भक्त माता के नाम पर पड़ा माना जाता है?","o":["माता शबरी","भक्त माता राजिम (राजिम तेलिन)","माता कौशल्या","माता कर्मा"],"a":1,"e":"लोककथा के अनुसार भक्त राजिम तेलिन की भक्ति से राजीव लोचन की प्रतिमा जुड़ी है; राजिम में उनका मंदिर भी है।"},
    {"q":"राजिम पंचकोसी यात्रा में निम्न में से कौन-सा स्थल शामिल नहीं है?","o":["पटेवा","फिंगेश्वर","खरौद","कोपरा"],"a":2,"e":"पंचकोसी के पाँच शिव धाम — पटेवा, चंपारण, बम्हनी, फिंगेश्वर, कोपरा; खरौद (लक्ष्मणेश्वर) शिवरीनारायण के पास है।"},
    {"q":"\"छत्तीसगढ़ की जगन्नाथपुरी\" किस धार्मिक स्थल को कहा जाता है?","o":["राजिम","खरौद","रतनपुर","शिवरीनारायण"],"a":3,"e":"मान्यता है कि भगवान जगन्नाथ (शबरी-नारायण) का मूल स्थान शिवरीनारायण था; इसलिए इसे छत्तीसगढ़ की जगन्नाथपुरी कहते हैं।"},
    {"q":"लक्ष्मणेश्वर महादेव का \"लक्षलिंग\" (एक लाख छिद्रों वाला शिवलिंग) कहाँ स्थित है?","o":["खरौद","राजिम","भोरमदेव","सिरपुर"],"a":0,"e":"खरौद (जांजगीर-चांपा) का लक्ष्मणेश्वर मंदिर \"छत्तीसगढ़ की काशी\" कहलाता है; यहाँ एक लाख चावल (\"लाखा चाउर\") चढ़ाने की परंपरा है।"},
    {"q":"होली के बाद (धूल पंचमी) नागा साधुओं की \"शिवजी की बारात\" के लिए प्रसिद्ध मेला कहाँ लगता है?","o":["राजिम","पीथमपुर (कलेश्वरनाथ)","देवबलौदा","महादेव घाट"],"a":1,"e":"पीथमपुर (जांजगीर-चांपा) के कलेश्वरनाथ मंदिर का मेला होली के बाद लगता है, जिसमें नागा साधु शिव-बारात निकालते हैं।"},
    {"q":"रायपुर के महादेव घाट पर प्रसिद्ध मेला किस अवसर पर लगता है?","o":["माघ पूर्णिमा","पौष पूर्णिमा","कार्तिक पूर्णिमा","चैत्र पूर्णिमा"],"a":2,"e":"खारुन नदी तट पर हटकेश्वर महादेव के पास कार्तिक पुन्नी मेला लगता है।"},
    {"q":"वाल्मीकि आश्रम व लव-कुश की जन्मस्थली की मान्यता वाले तुरतुरिया में मेला कब लगता है?","o":["माघ पूर्णिमा","कार्तिक पूर्णिमा","रामनवमी","पौष पूर्णिमा"],"a":3,"e":"तुरतुरिया (बलौदाबाजार-भाटापारा) में पौष पूर्णिमा (छेरछेरा) पर मेला लगता है; यहाँ बौद्ध भिक्षुणी विहार के अवशेष भी हैं।"},
    {"q":"चंपारण (रायपुर) में वल्लभाचार्य जयंती का मेला किस तिथि को लगता है?","o":["वैशाख कृष्ण एकादशी","माघ पूर्णिमा","कार्तिक शुक्ल एकादशी","चैत्र शुक्ल नवमी"],"a":0,"e":"वल्लभाचार्य का जन्म 1479 ई. में वैशाख कृष्ण एकादशी को चंपारण में हुआ; इसी दिन यहाँ उत्सव-मेला होता है।"},
    {"q":"महाप्रभु वल्लभाचार्य द्वारा प्रवर्तित भक्ति-मार्ग का नाम क्या है?","o":["ज्ञानमार्ग","पुष्टिमार्ग","सहज मार्ग","निर्गुण मार्ग"],"a":1,"e":"वल्लभाचार्य ने पुष्टिमार्ग चलाया; उनका दार्शनिक मत \"शुद्धाद्वैत\" कहलाता है।"},
    {"q":"वल्लभाचार्य का दार्शनिक सिद्धांत किस नाम से जाना जाता है?","o":["द्वैत","विशिष्टाद्वैत","शुद्धाद्वैत","द्वैताद्वैत"],"a":2,"e":"शुद्धाद्वैत वल्लभाचार्य का मत है; विशिष्टाद्वैत रामानुज का और द्वैत मध्वाचार्य का।"},
    {"q":"वल्लभाचार्य के पिता का नाम क्या था?","o":["विट्ठलनाथ","गोपीनाथ","केशव भट्ट","लक्ष्मण भट्ट"],"a":3,"e":"पिता लक्ष्मण भट्ट और माता इल्लमागारु तेलुगु ब्राह्मण थे, जो यात्रा के दौरान चंपारण्य पहुँचे थे; विट्ठलनाथ वल्लभाचार्य के पुत्र थे।"},
    {"q":"गुरु घासीदास का जन्म किस वर्ष हुआ था?","o":["1756","1820","1857","1701"],"a":0,"e":"गुरु घासीदास का जन्म 18 दिसंबर 1756 को गिरौदपुरी में हुआ; इसी तिथि पर गुरु घासीदास जयंती मनाई जाती है।"},
    {"q":"गुरु घासीदास के माता-पिता कौन थे?","o":["सफुरा और बालकदास","अमरौतिन और महंगू दास","आमिन और धर्मदास","फुलकैना और कल्याण साय"],"a":1,"e":"पिता महंगू दास, माता अमरौतिन; सफुरा माता उनकी पत्नी और बालकदास उनके पुत्र थे।"},
    {"q":"गुरु घासीदास की पत्नी के रूप में सतनामी समाज में किन्हें पूजा जाता है?","o":["मिनीमाता","राजिम माता","सफुरा माता","अमरौतिन माता"],"a":2,"e":"सफुरा माता गुरु घासीदास की पत्नी थीं; मिनीमाता 20वीं सदी की सांसद व समाजसेवी थीं।"},
    {"q":"गुरु घासीदास ने किस पहाड़ पर औंरा-धौंरा वृक्ष के नीचे तपस्या कर ज्ञान प्राप्त किया?","o":["मैकल पहाड़","रामगढ़ पहाड़","डोंगरगढ़ पहाड़","छाता पहाड़"],"a":3,"e":"गिरौदपुरी के पास छाता पहाड़ पर औंरा-धौंरा वृक्ष के नीचे तपस्या की मान्यता है; वहाँ चरण कुंड और अमृत कुंड भी हैं।"},
    {"q":"गुरु घासीदास का प्रसिद्ध संदेश \"मनखे-मनखे एक समान\" किस विचार को व्यक्त करता है?","o":["सभी मनुष्य समान हैं (जाति-भेद का विरोध)","मूर्ति पूजा श्रेष्ठ है","शाकाहार अनिवार्य है","गुरु-भक्ति सर्वोपरि है"],"a":0,"e":"यह संदेश मनुष्य-मनुष्य में समानता और जाति-भेद के विरोध का है — सतनाम पंथ का केंद्रीय विचार।"},
    {"q":"निम्नलिखित में से कौन-सा गुरु घासीदास के सात सिद्धांतों में शामिल नहीं है?","o":["सतनाम पर विश्वास","मूर्ति पूजा करना","जीव हत्या न करना","दोपहर में हल न चलाना"],"a":1,"e":"गुरु घासीदास ने मूर्ति पूजा का निषेध किया था; शेष तीनों उनके सात सिद्धांतों में शामिल हैं।"},
    {"q":"रायपुर का \"महंत घासीदास स्मारक संग्रहालय\" किसके नाम पर है?","o":["सतनाम पंथ के प्रवर्तक गुरु घासीदास","दूधाधारी मठ के महंत","नांदगांव के राजा महंत घासीदास","कबीरपंथ के आचार्य"],"a":2,"e":"यह संग्रहालय (1875) नांदगांव (राजनांदगांव) के राजा महंत घासीदास के नाम पर है — गुरु घासीदास से इसे जोड़ना सामान्य भूल है।"},
    {"q":"गुरु घासीदास विश्वविद्यालय, बिलासपुर को केंद्रीय विश्वविद्यालय का दर्जा किस वर्ष मिला?","o":["1983","2000","2012","2009"],"a":3,"e":"विश्वविद्यालय 1983 में स्थापित हुआ और केंद्रीय विश्वविद्यालय अधिनियम 2009 से केंद्रीय विश्वविद्यालय बना।"},
    {"q":"रामनामी संप्रदाय के संस्थापक कौन माने जाते हैं?","o":["परशुराम भारद्वाज","गहिरा गुरु","धनी धर्मदास","गुरु बालकदास"],"a":0,"e":"चारपारा गाँव के परशुराम भारद्वाज ने 1890 के दशक में रामनामी समाज की नींव रखी।"},
    {"q":"रामनामी संप्रदाय के अनुयायियों की सबसे प्रमुख पहचान क्या है?","o":["सफेद ध्वज वाला जैतखाम","शरीर पर \"राम-राम\" का गोदना","कंठी और चौका आरती","गेरुआ वस्त्र और जटा"],"a":1,"e":"रामनामी पूरे शरीर (नखशिख) तक \"राम-राम\" गुदवाते हैं, मोरपंख का मुकुट और राम-नाम छपी ओढ़नी पहनते हैं; जैतखाम सतनामियों का प्रतीक है।"},
    {"q":"बस्तर दशहरा के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. फूल रथ आठ पहियों का होता है।<br>2. भीतर रैनी की रस्म विजयादशमी को होती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — फूल रथ चार पहियों का, विजय रथ आठ पहियों का होता है।<br>कथन 2 सही — विजयादशमी को भीतर रैनी में विजय रथ \"चुराकर\" कुम्हड़ाकोट ले जाया जाता है।"},
    {"q":"सूची-I (बस्तर दशहरा की रस्म) को सूची-II (समय) से सुमेलित कीजिए —<br>(A) पाट जात्रा (B) काछन गादी (C) निशा जात्रा (D) बाहर रैनी<br>1. आश्विन अमावस्या 2. आश्विन शुक्ल एकादशी 3. श्रावण अमावस्या 4. अष्टमी की मध्यरात्रि","o":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-4, B-1, C-3, D-2"],"a":0,"e":"पाट जात्रा — श्रावण (हरेली) अमावस्या।<br>काछन गादी — आश्विन अमावस्या।<br>निशा जात्रा — अष्टमी की आधी रात।<br>बाहर रैनी — एकादशी (दशहरे के अगले दिन)।"},
    {"q":"बस्तर दशहरा की निम्नलिखित रस्मों को घटित होने के क्रम में व्यवस्थित कीजिए —<br>1. मावली परघाव<br>2. डेरी गड़ाई<br>3. निशा जात्रा<br>4. काछन गादी","o":["4, 2, 3, 1","2, 3, 4, 1","2, 4, 3, 1","4, 2, 1, 3"],"a":2,"e":"डेरी गड़ाई (भाद्रपद) → काछन गादी (आश्विन अमावस्या) → निशा जात्रा (अष्टमी रात्रि) → मावली परघाव (नवमी)।"},
    {"q":"अभिकथन (A): बस्तर दशहरा में रावण का पुतला दहन नहीं किया जाता।<br>कारण (R): बस्तर दशहरा राम-रावण कथा का नहीं, बल्कि देवी दंतेश्वरी की आराधना का पर्व है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही — बस्तर दशहरे में रावण दहन की परंपरा नहीं है।<br>R सही और A की व्याख्या — पूरा पर्व माँ दंतेश्वरी (मावली) व ग्राम देवताओं की आराधना पर केंद्रित है।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (बस्तर दशहरा की रस्म — संबद्ध तथ्य) सही सुमेलित नहीं है?","o":["पाट जात्रा — ठुरलू खोटला","जोगी बिठाई — हल्बा जाति","काछन गादी — पनका जाति की कन्या","मुरिया दरबार — कुम्हड़ाकोट"],"a":3,"e":"मुरिया दरबार सिरासार भवन में होता है; कुम्हड़ाकोट भीतर रैनी/बाहर रैनी (रथ ले जाने और नवाखानी) से जुड़ा है। शेष तीनों युग्म सही हैं।"},
    {"q":"बस्तर दशहरा की निम्नलिखित रस्मों को सही क्रम में व्यवस्थित कीजिए —<br>1. भीतर रैनी<br>2. जोगी बिठाई<br>3. मुरिया दरबार<br>4. बेल पूजा","o":["2, 1, 4, 3","2, 4, 1, 3","4, 2, 1, 3","2, 4, 3, 1"],"a":1,"e":"जोगी बिठाई (प्रतिपदा) → बेल पूजा (नवरात्रि के मध्य) → भीतर रैनी (दशमी) → मुरिया दरबार (बाहर रैनी के बाद)।"},
    {"q":"अभिकथन (A): बस्तर दशहरे में आठ पहियों वाला विजय रथ दशमी और एकादशी को चलाया जाता है।<br>कारण (R): चार पहियों वाला फूल रथ नवरात्रि की द्वितीया से सप्तमी तक परिक्रमा करता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — विजय रथ भीतर रैनी और बाहर रैनी में चलता है।<br>R सही — फूल रथ नवरात्रि के आरंभिक दिनों में चलता है; पर यह A का कारण नहीं, एक अलग तथ्य है।"},
    {"q":"गोंचा पर्व के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. गोंचा रथयात्रा आषाढ़ शुक्ल द्वितीया को निकलती है।<br>2. गोंचा पर्व का समापन देवउठनी एकादशी को होता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — रथयात्रा आषाढ़ शुक्ल द्वितीया को होती है।<br>कथन 2 गलत — समापन देवशयनी एकादशी (आषाढ़ शुक्ल 11) को होता है; देवउठनी कार्तिक में आती है।"},
    {"q":"गोंचा पर्व की निम्नलिखित रस्मों को सही क्रम में व्यवस्थित कीजिए —<br>1. बाहुड़ा गोंचा<br>2. चंदन जात्रा<br>3. हेरा पंचमी<br>4. नेत्रोत्सव","o":["2, 3, 4, 1","4, 2, 3, 1","2, 4, 1, 3","2, 4, 3, 1"],"a":3,"e":"चंदन जात्रा (देव-स्नान) → नेत्रोत्सव → गोंचा रथयात्रा → हेरा पंचमी → बाहुड़ा गोंचा (वापसी)।"},
    {"q":"अभिकथन (A): जगदलपुर का गोंचा पर्व आषाढ़ माह में मनाया जाता है।<br>कारण (R): गोंचा पर्व की शुरुआत बस्तर के राजा दलपत देव ने की थी।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही — गोंचा आषाढ़ शुक्ल द्वितीया की रथयात्रा है।<br>R गलत — यह परंपरा महाराजा पुरुषोत्तम देव की जगन्नाथ पुरी यात्रा से जोड़ी जाती है; दलपत देव ने राजधानी जगदलपुर स्थानांतरित की थी।"},
    {"q":"सूची-I (पर्व) को सूची-II (तिथि) से सुमेलित कीजिए —<br>(A) आठे कन्हैया (B) करमा (C) अक्ती (D) जेठौनी<br>1. वैशाख शुक्ल तृतीया 2. कार्तिक शुक्ल एकादशी 3. भाद्रपद कृष्ण अष्टमी 4. भाद्रपद शुक्ल एकादशी","o":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-1, B-4, C-3, D-2"],"a":2,"e":"आठे कन्हैया — भाद्रपद कृष्ण अष्टमी।<br>करमा — भाद्रपद शुक्ल एकादशी।<br>अक्ती — वैशाख शुक्ल तृतीया।<br>जेठौनी — कार्तिक शुक्ल एकादशी।"},
    {"q":"कमरछठ (हलषष्ठी) के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. यह बलराम की जयंती के रूप में मनाई जाती है।<br>2. इस व्रत में भैंस के दूध-दही का उपयोग होता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — भाद्रपद कृष्ण षष्ठी हलधर बलराम का जन्मदिन है।<br>कथन 2 सही — गाय के स्थान पर भैंस का दूध, दही, घी प्रयोग होता है।"},
    {"q":"चैत्र माह से आरंभ करते हुए निम्नलिखित पर्वों को वर्ष में आने के क्रम में व्यवस्थित कीजिए —<br>1. पोला<br>2. अक्ती<br>3. हरेली<br>4. जेठौनी","o":["2, 3, 1, 4","3, 2, 1, 4","2, 1, 3, 4","2, 3, 4, 1"],"a":0,"e":"अक्ती (वैशाख) → हरेली (श्रावण अमावस्या) → पोला (भाद्रपद अमावस्या) → जेठौनी (कार्तिक शुक्ल एकादशी)।"},
    {"q":"अभिकथन (A): हरेली पर किसान अपने कृषि औजारों की पूजा करते हैं।<br>कारण (R): हरेली तक खरीफ की बोआई का प्रमुख कार्य पूरा हो चुका होता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही — हल, कुदाल, गैंती आदि धोकर पूजे जाते हैं।<br>R सही और व्याख्या — बोआई पूरी होने पर औजारों के प्रति कृतज्ञता प्रकट करने हेतु पूजा होती है।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म सही सुमेलित नहीं है?","o":["अगहन बिरस्पत — लक्ष्मी पूजा","सोहई — गोवर्धन पूजा","ईसर देव — गौरा-गौरी पूजा","आठे कन्हैया — रामनवमी"],"a":3,"e":"आठे कन्हैया जन्माष्टमी (भाद्रपद कृष्ण अष्टमी) से जुड़ा है, रामनवमी से नहीं। शेष तीनों युग्म सही हैं।"},
    {"q":"छेरछेरा पर्व के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. लोककथा इसे रानी फुलकैना द्वारा प्रजा में अन्न-धन बाँटने से जोड़ती है।<br>2. यह पौष अमावस्या को मनाया जाता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — राजा कल्याण साय के लौटने पर रानी फुलकैना ने दान किया था।<br>कथन 2 गलत — छेरछेरा पौष पूर्णिमा (पूस पुन्नी) को होता है।"},
    {"q":"सूची-I (मेला-स्थल) को सूची-II (जिला) से सुमेलित कीजिए —<br>(A) दामाखेड़ा (B) कुदुरमाल (C) चंपारण (D) खल्लारी<br>1. रायपुर 2. महासमुंद 3. बलौदाबाजार-भाटापारा 4. कोरबा","o":["A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-1, B-4, C-3, D-2"],"a":1,"e":"दामाखेड़ा — बलौदाबाजार-भाटापारा।<br>कुदुरमाल — कोरबा (हसदेव तट)।<br>चंपारण — रायपुर।<br>खल्लारी — महासमुंद।"},
    {"q":"सूची-I (मेला) को सूची-II (अवसर) से सुमेलित कीजिए —<br>(A) महादेव घाट (B) तुरतुरिया (C) खल्लारी (D) गिरौदपुरी<br>1. फाल्गुन शुक्ल पंचमी 2. कार्तिक पूर्णिमा 3. चैत्र पूर्णिमा 4. पौष पूर्णिमा","o":["A-2, B-3, C-4, D-1","A-4, B-2, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1"],"a":3,"e":"महादेव घाट — कार्तिक पूर्णिमा।<br>तुरतुरिया — पौष पूर्णिमा।<br>खल्लारी — चैत्र पूर्णिमा।<br>गिरौदपुरी — फाल्गुन शुक्ल पंचमी से सप्तमी।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. गिरौदपुरी बलौदाबाजार-भाटापारा जिले में स्थित है।<br>2. गुरु घासीदास जयंती 18 दिसंबर को मनाई जाती है।<br>3. सतनाम पंथ के जैतखाम पर भगवा ध्वज लगाया जाता है।<br>सही कथन हैं —","o":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":0,"e":"कथन 1 सही — गिरौदपुरी बलौदाबाजार-भाटापारा जिले में है।<br>कथन 2 सही — 18 दिसंबर 1756 जन्मतिथि है।<br>कथन 3 गलत — जैतखाम पर सफेद ध्वज (सत्य व शांति का प्रतीक) लगता है।"},
    {"q":"अभिकथन (A): सतनाम पंथ में मूर्ति पूजा नहीं की जाती।<br>कारण (R): गुरु घासीदास ने निराकार \"सतनाम\" की उपासना का उपदेश दिया।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही — मूर्ति पूजा निषेध सात सिद्धांतों में है।<br>R सही और व्याख्या — सत्य-नाम (निराकार) की उपासना के कारण ही मूर्ति पूजा त्यागी गई।"},
    {"q":"कबीरपंथ के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. धनी धर्मदास कबीर के प्रमुख शिष्य थे और बांधवगढ़ के वैश्य थे।<br>2. कुदुरमाल का कबीरपंथी तीर्थ महानदी के तट पर स्थित है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — धनी धर्मदास बांधवगढ़ के धनी वैश्य थे, जो कबीर के शिष्य बने।<br>कथन 2 गलत — कुदुरमाल कोरबा जिले में हसदेव नदी के तट पर है।"},
    {"q":"सूची-I (संत/प्रवर्तक) को सूची-II (संबद्ध स्थान) से सुमेलित कीजिए —<br>(A) गुरु घासीदास (B) वल्लभाचार्य (C) परशुराम भारद्वाज (D) गहिरा गुरु<br>1. चंपारण 2. चारपारा 3. गहिरा गाँव 4. गिरौदपुरी","o":["A-4, B-1, C-3, D-2","A-1, B-4, C-2, D-3","A-4, B-2, C-1, D-3","A-4, B-1, C-2, D-3"],"a":3,"e":"गुरु घासीदास — गिरौदपुरी।<br>वल्लभाचार्य — चंपारण।<br>परशुराम भारद्वाज (रामनामी) — चारपारा।<br>गहिरा गुरु — गहिरा गाँव (रायगढ़)।"},
    {"q":"सूची-I (पंथ/परंपरा) को सूची-II (पहचान) से सुमेलित कीजिए —<br>(A) सतनाम पंथ (B) कबीरपंथ (C) रामनामी संप्रदाय (D) पुष्टिमार्ग<br>1. शरीर पर राम-नाम का गोदना 2. जैतखाम 3. चौका आरती व कंठी 4. शुद्धाद्वैत दर्शन","o":["A-2, B-3, C-1, D-4","A-3, B-2, C-1, D-4","A-2, B-1, C-3, D-4","A-2, B-3, C-4, D-1"],"a":0,"e":"सतनाम — जैतखाम।<br>कबीरपंथ — चौका आरती, कंठी।<br>रामनामी — राम-नाम गोदना।<br>पुष्टिमार्ग (वल्लभाचार्य) — शुद्धाद्वैत।"},
    {"q":"सूची-I (देवी) को सूची-II (स्थान) से सुमेलित कीजिए —<br>(A) महामाया (शक्तिपीठ) (B) बम्लेश्वरी (C) चंद्रहासिनी (D) खल्लारी माता<br>1. डोंगरगढ़ 2. महासमुंद 3. रतनपुर 4. चंद्रपुर","o":["A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2"],"a":1,"e":"महामाया शक्तिपीठ — रतनपुर।<br>बम्लेश्वरी — डोंगरगढ़।<br>चंद्रहासिनी — चंद्रपुर (महानदी-मांड संगम)।<br>खल्लारी माता — महासमुंद।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (देवी — स्थान) सही सुमेलित नहीं है?","o":["चंडी माता — घुंचापाली","अंगारमोती — गंगरेल","बिलाई माता — कोरबा","गंगा मैया — झलमला"],"a":2,"e":"बिलाई माता (विंध्यवासिनी) धमतरी में हैं, कोरबा में नहीं। चंडी माता घुंचापाली (बागबाहरा), अंगारमोती गंगरेल (धमतरी), गंगा मैया झलमला (बालोद) — सही।"},
    {"q":"कुनकुरी महागिरजाघर के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. यह जशपुर जिले में स्थित है।<br>2. इसका लोकार्पण 1962 में हुआ था।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — कुनकुरी जशपुर जिले में है।<br>कथन 2 गलत — 1962 में नींव (बिशप स्टैनिसलॉस तिग्गा) रखी गई; लोकार्पण 27 अक्टूबर 1979 को हुआ।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. रेव. ऑस्कर लोर ने 1868 में बिश्रामपुर में मिशन की स्थापना की।<br>2. ऑस्कर लोर जर्मन इवेंजेलिकल मिशन से जुड़े थे।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 1868 में बिश्रामपुर मिशन छत्तीसगढ़ का प्रथम ईसाई मिशन माना जाता है।<br>कथन 2 सही — लोर जर्मन इवेंजेलिकल मिशन सोसाइटी के अग्रणी मिशनरी थे।"},
    {"q":"सूची-I (धार्मिक स्मारक) को सूची-II (स्थान) से सुमेलित कीजिए —<br>(A) भांड देवल (B) उवसग्गहरं पार्श्व तीर्थ (C) चंद्रगिरि तीर्थ (D) आनंदप्रभु कुटी विहार<br>1. सिरपुर 2. आरंग 3. नगपुरा 4. डोंगरगढ़","o":["A-2, B-3, C-4, D-1","A-3, B-2, C-4, D-1","A-2, B-4, C-3, D-1","A-2, B-3, C-1, D-4"],"a":0,"e":"भांड देवल (जैन) — आरंग।<br>उवसग्गहरं पार्श्व तीर्थ — नगपुरा (दुर्ग)।<br>चंद्रगिरि (जैन) — डोंगरगढ़।<br>आनंदप्रभु कुटी विहार (बौद्ध) — सिरपुर।"},
    {"q":"सूची-I (तिथि) को सूची-II (प्रतीक दिवस) से सुमेलित कीजिए —<br>(A) 10 दिसंबर (B) 10 फरवरी (C) 18 दिसंबर (D) 21 दिसंबर<br>1. पं. सुंदरलाल शर्मा जयंती 2. भूमकाल स्मृति दिवस 3. शहीद वीर नारायण सिंह बलिदान दिवस 4. गुरु घासीदास जयंती","o":["A-2, B-3, C-4, D-1","A-3, B-2, C-1, D-4","A-3, B-2, C-4, D-1","A-4, B-2, C-3, D-1"],"a":2,"e":"10 दिसंबर — वीर नारायण सिंह को 1857 में फाँसी।<br>10 फरवरी — 1910 का भूमकाल।<br>18 दिसंबर — गुरु घासीदास जयंती।<br>21 दिसंबर — पं. सुंदरलाल शर्मा जयंती।"},
    {"q":"निम्नलिखित घटनाओं को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. बिश्रामपुर मिशन की स्थापना<br>2. गुरु घासीदास का जन्म<br>3. वल्लभाचार्य का जन्म<br>4. प्रथम मुरिया दरबार","o":["3, 2, 4, 1","2, 3, 1, 4","3, 1, 2, 4","3, 2, 1, 4"],"a":3,"e":"वल्लभाचार्य (1479) → गुरु घासीदास (1756) → बिश्रामपुर मिशन (1868) → प्रथम मुरिया दरबार (1876)।"},
    {"q":"निम्नलिखित को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. भोरमदेव मंदिर का निर्माण<br>2. ह्वेनसांग की सिरपुर यात्रा<br>3. कुनकुरी महागिरजाघर का लोकार्पण<br>4. भूमकाल विद्रोह","o":["2, 1, 4, 3","1, 2, 4, 3","2, 1, 3, 4","2, 4, 1, 3"],"a":0,"e":"ह्वेनसांग (639 ई.) → भोरमदेव (1089 ई.) → भूमकाल (1910) → कुनकुरी लोकार्पण (1979)।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. चंदखुरी में माता कौशल्या का मंदिर जलसेन तालाब के मध्य स्थित है।<br>2. सिहावा पर्वत शिवनाथ नदी का उद्गम स्थल है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — चंदखुरी (रायपुर) को कौशल्या की जन्मभूमि माना जाता है।<br>कथन 2 गलत — सिहावा (धमतरी) महानदी का उद्गम है; शृंगी ऋषि आश्रम भी यहीं है।"},
    {"q":"अभिकथन (A): शिवरीनारायण को \"छत्तीसगढ़ की जगन्नाथपुरी\" कहा जाता है।<br>कारण (R): शिवरीनारायण में महानदी, शिवनाथ और जोंक नदियों का संगम है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — कारण: जगन्नाथ (शबरी-नारायण) का मूल स्थान यहीं होने की मान्यता।<br>R सही, पर व्याख्या नहीं — त्रिवेणी संगम एक अलग भौगोलिक तथ्य है।"},
    {"q":"अभिकथन (A): रामनामी संप्रदाय के लोग मंदिरों में राम की मूर्ति की पूजा करते हैं।<br>कारण (R): रामनामी राम के नाम-जप और रामचरितमानस पाठ को सर्वोच्च मानते हैं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":3,"e":"A गलत — रामनामी मूर्ति पूजा और मंदिर-आश्रय नहीं अपनाते।<br>R सही — वे \"राम\" नाम को ही उपास्य मानकर शरीर पर गुदवाते और भजन करते हैं।"},
    {"q":"रामनामी संप्रदाय के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. बड़े भजन मेला पौष शुक्ल एकादशी से त्रयोदशी तक होता है।<br>2. बड़े भजन मेला प्रतिवर्ष एक ही गाँव में लगता है।<br>3. अनुयायी मोरपंख से बना मुकुट धारण करते हैं।<br>सही कथन हैं —","o":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":2,"e":"कथन 1 सही — पौष शुक्ल 11 से 13।<br>कथन 2 गलत — मेला हर वर्ष महानदी तट के अलग-अलग गाँवों में बारी-बारी लगता है।<br>कथन 3 सही — मोरपंख का मुकुट उनकी पहचान है।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (पर्व/जयंती — संबद्ध समुदाय) सही सुमेलित नहीं है?","o":["सरहुल — उरांव","मातर — राउत","गौरा-गौरी — गोंड","माता कर्मा जयंती — सतनामी समाज"],"a":3,"e":"माता कर्मा साहू (तेली) समाज की आराध्य हैं। सरहुल उरांव, मातर राउत और गौरा-गौरी गोंड समाज से जुड़े हैं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. चंपारण में स्थित चंपकेश्वर महादेव राजिम पंचकोसी यात्रा का भाग है।<br>2. चंपारण महासमुंद जिले में स्थित है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — पंचकोसी के पाँच धामों में चंपारण का चंपकेश्वर शामिल है।<br>कथन 2 गलत — चंपारण रायपुर जिले में है।"},
    {"q":"संत गहिरा गुरु के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. उन्होंने 1943 में \"सनातन धर्म संत समाज\" की स्थापना की।<br>2. अंबिकापुर स्थित सरगुजा विश्वविद्यालय का नाम उनके नाम पर रखा गया।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — सनातन धर्म संत समाज के माध्यम से जनजातियों में नशामुक्ति व स्वच्छता का प्रचार किया।<br>कथन 2 सही — अब यह \"संत गहिरा गुरु विश्वविद्यालय\" है।"},
    {"q":"अभिकथन (A): भोजली के माध्यम से दो व्यक्ति आजीवन मित्रता (मितानी) का संबंध जोड़ते हैं।<br>कारण (R): भोजली नवरात्रि में देवी की सेवा के लिए बोई जाती है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही — \"भोजली बदना\" मितानी की परंपरा है।<br>R गलत — भोजली श्रावण में बोई जाती है; नवरात्रि में बोए जाने वाले अंकुर \"जंवारा\" कहलाते हैं।"},
    {"q":"कबीरधाम जिले का नाम किस कारण पड़ा?","o":["यहाँ कबीर का जन्म हुआ था","कवर्धा कबीरपंथ की गद्दी का केंद्र रहा था","यहाँ कबीर की समाधि है","यहाँ कबीर ने बीजक लिखा"],"a":1,"e":"कवर्धा में धर्मदासी कबीरपंथ की गद्दी रही थी, इसलिए जिले का नाम कबीरधाम रखा गया; वर्तमान प्रमुख गद्दी दामाखेड़ा में है।"},
    {"q":"धनी धर्मदास के पुत्र, जिनसे कबीरपंथ की वंश-गुरु परंपरा आरंभ मानी जाती है, कौन थे?","o":["उग्रनाम साहब","प्रकाशमुनि नाम साहब","मुक्तामणि (चूड़ामणि) नाम साहब","सुदर्शन नाम साहब"],"a":2,"e":"मुक्तामणि नाम साहब धर्मदासी शाखा के प्रथम वंशगुरु माने जाते हैं; कबीर द्वारा 42 वंश तक गद्दी चलने का आशीर्वाद मान्य है।"},
    {"q":"कबीरपंथ की धर्मदासी परंपरा में कबीर द्वारा कितने वंशों तक गद्दी चलने का आशीर्वाद माना जाता है?","o":["12","24","36","42"],"a":3,"e":"धर्मदासी परंपरा \"42 वंश\" के आशीर्वाद को मानती है; वंशगुरु \"नाम साहब\" कहलाते हैं।"},
    {"q":"कोरबा जिले में हसदेव नदी के तट पर स्थित कबीरपंथी तीर्थ, जहाँ माघ पूर्णिमा पर मेला लगता है, कौन-सा है?","o":["कुदुरमाल","दामाखेड़ा","मदकू द्वीप","सेतगंगा"],"a":0,"e":"कुदुरमाल में कबीरपंथी गुरुओं की समाधियाँ हैं; दामाखेड़ा बलौदाबाजार-भाटापारा जिले में है।"},
    {"q":"गिरौदपुरी मेले के समापन पर कौन-सी प्रमुख परंपरा निभाई जाती है?","o":["रथ खींचना","जैतखाम पर सफेद झंडा चढ़ाना","भोजली विसर्जन","ज्योति कलश स्थापना"],"a":1,"e":"फाल्गुन शुक्ल पंचमी से सप्तमी तक चलने वाले मेले में जैतखाम पर सफेद ध्वज चढ़ाया जाता है।"},
    {"q":"सतनामी परंपरा में \"भंडारपुरी\" किस रूप में प्रसिद्ध है?","o":["गुरु घासीदास की जन्मस्थली","गुरु घासीदास की तपोभूमि","गुरु-गद्दी/गुरुद्वारा का स्थल","रामनामियों का मेला-स्थल"],"a":2,"e":"भंडारपुरी सतनामियों का गुरुद्वारा (गुरु-गद्दी) स्थल है; जन्मस्थली गिरौदपुरी और तपोभूमि छाता पहाड़ है।"},
    {"q":"रामनामी संप्रदाय के संस्थापक परशुराम भारद्वाज का गाँव \"चारपारा\" किस क्षेत्र में है?","o":["मालखरौदा क्षेत्र","अबूझमाड़","मैनपाट","सिहावा"],"a":0,"e":"चारपारा मालखरौदा क्षेत्र (महानदी अंचल) में है; रामनामी मुख्यतः महानदी तटीय जिलों में बसे हैं।"},
    {"q":"डोंगरगढ़ की माँ बम्लेश्वरी से जुड़ी लोककथा किस प्रेम-कथा से संबंधित है?","o":["लोरिक-चंदा","कामकंदला-माधवनल","ढोला-मारू","हीर-रांझा"],"a":1,"e":"डोंगरगढ़ (प्राचीन राजा वीरसेन व उनके वंशजों की नगरी) की नर्तकी कामकंदला और माधवनल की प्रेम-कथा बम्लेश्वरी से जोड़ी जाती है; लोरिक-चंदा चंदैनी गाथा है।"},
    {"q":"डोंगरगढ़ की पहाड़ी पर स्थित बौद्ध स्थल, जहाँ भगवान बुद्ध की विशाल प्रतिमा है, कौन-सा है?","o":["चंद्रगिरि","आनंदप्रभु विहार","प्रज्ञागिरि","स्वस्तिक विहार"],"a":2,"e":"प्रज्ञागिरि बौद्ध स्थल है; चंद्रगिरि डोंगरगढ़ का जैन तीर्थ है और आनंदप्रभु व स्वस्तिक विहार सिरपुर में हैं।"},
    {"q":"दिगंबर जैन आचार्य विद्यासागर ने फरवरी 2024 में किस तीर्थ पर समाधि ली?","o":["नगपुरा","आरंग","मल्हार","चंद्रगिरि (डोंगरगढ़)"],"a":3,"e":"18 फरवरी 2024 को आचार्य विद्यासागर ने डोंगरगढ़ के चंद्रगिरि तीर्थ पर सल्लेखना द्वारा समाधि ली।"},
    {"q":"\"मिनी तिब्बत\" के रूप में प्रसिद्ध, तिब्बती शरणार्थियों की बस्ती वाला स्थान कौन-सा है?","o":["मैनपाट","चैतुरगढ़","केशकाल","चिल्फी घाटी"],"a":0,"e":"1962-63 में सरगुजा के मैनपाट में तिब्बती शरणार्थी बसाए गए; यहाँ बौद्ध मठ हैं।"},
    {"q":"सिरपुर का \"आनंदप्रभु कुटी विहार\" किस राजा के शासनकाल से संबद्ध है?","o":["तीवरदेव","महाशिवगुप्त बालार्जुन","हर्षगुप्त","रत्नदेव प्रथम"],"a":1,"e":"भिक्षु आनंदप्रभु ने पांडुवंशी (सोमवंशी) राजा महाशिवगुप्त बालार्जुन के काल में यह विहार बनवाया।"},
    {"q":"चीनी यात्री ह्वेनसांग ने सिरपुर (श्रीपुर) की यात्रा लगभग किस वर्ष की?","o":["405 ई.","1089 ई.","639 ई.","1206 ई."],"a":2,"e":"ह्वेनसांग 639 ई. के आसपास दक्षिण कोसल (सिरपुर) आया था और यहाँ के बौद्ध विहारों का वर्णन किया।"},
    {"q":"लुतरा शरीफ की दरगाह किस सूफी संत से संबंधित है?","o":["हज़रत निज़ामुद्दीन","ख्वाजा मोइनुद्दीन चिश्ती","बाबा फरीद","बाबा सैयद इंसान अली शाह"],"a":3,"e":"बिलासपुर जिले में सीपत के पास लुतरा शरीफ में बाबा सैयद इंसान अली शाह की दरगाह है, जहाँ वार्षिक उर्स लगता है।"},
    {"q":"शिवनाथ नदी के द्वीप पर लगने वाला, सौ वर्ष से अधिक पुराना ईसाई मेला कहाँ आयोजित होता है?","o":["मदकू द्वीप","कुनकुरी","मलखरौदा","बिश्रामपुर"],"a":0,"e":"मदकू द्वीप पर फरवरी में ईसाई मेला लगता है; यहाँ उत्खनन से प्राचीन शिव मंदिरों के अवशेष भी मिले हैं।"},
    {"q":"रायपुर के दूधाधारी मठ का यह नाम क्यों पड़ा?","o":["मठ में दूध की डेयरी थी","संस्थापक महंत बलभद्र दास केवल दूध का सेवन करते थे","मठ दूध नदी के तट पर है","यहाँ दूध से अभिषेक होता है"],"a":1,"e":"महंत बलभद्र दास केवल दूध पर रहते थे, इसलिए \"दूधाधारी\" कहलाए; मठ रामानंदी वैष्णव परंपरा का है।"},
    {"q":"स्वामी विवेकानंद ने किशोरावस्था के लगभग दो वर्ष (1877–79) छत्तीसगढ़ के किस नगर में बिताए?","o":["बिलासपुर","जगदलपुर","रायपुर","दुर्ग"],"a":2,"e":"नरेंद्रनाथ अपने पिता विश्वनाथ दत्त के साथ रायपुर में रहे; बूढ़ा तालाब का नाम अब \"विवेकानंद सरोवर\" है।"},
    {"q":"भोरमदेव मंदिर परिसर के पास स्थित \"मड़वा महल\" किस प्रकार का स्मारक है?","o":["युद्ध-विजय स्मारक","जैन मंदिर","बौद्ध स्तूप","राजवंशीय विवाह का स्मारक"],"a":3,"e":"मड़वा (मंडप) महल 1349 ई. में फणिनागवंशी रामचंद्र देव और कलचुरि राजकुमारी अंबिका देवी के विवाह की स्मृति में बना; इसे \"दूल्हादेव\" भी कहते हैं।"},
    {"q":"देवबलौदा का कलचुरि कालीन शिव मंदिर, जहाँ महाशिवरात्रि पर मेला लगता है, किस जिले में है?","o":["दुर्ग","कबीरधाम","जांजगीर-चांपा","महासमुंद"],"a":0,"e":"देवबलौदा (भिलाई-चरोदा क्षेत्र) दुर्ग जिले में है; यहाँ का शिव मंदिर कलचुरि काल का है।"},
    {"q":"सरगुजा का \"रामगढ़ महोत्सव\" किस तिथि को आयोजित किया जाता है?","o":["कार्तिक पूर्णिमा","आषाढ़ माह के प्रथम दिवस","माघ पूर्णिमा","रामनवमी"],"a":1,"e":"कालिदास के मेघदूत की पंक्ति \"आषाढस्य प्रथम दिवसे\" की स्मृति में रामगढ़ महोत्सव आषाढ़ के प्रथम दिन होता है।"},
    {"q":"उरांव जनजाति के सरहुल पर्व में पूजा कराने वाले पुजारी को क्या कहते हैं?","o":["बैगा","सिरहा","पाहन","गुनिया"],"a":2,"e":"उरांव समाज का गाँव-पुजारी \"पाहन\" कहलाता है; पूजा पवित्र साल-कुंज \"सरना\" में होती है।"},
    {"q":"करमा पर्व में पूजी जाने वाली देवी कौन हैं?","o":["दंतेश्वरी","मावली","शीतला","करमसेनी देवी"],"a":3,"e":"करम वृक्ष की डाल आँगन में गाड़कर करमसेनी देवी की पूजा होती है और करमा-धरमा भाइयों की कथा सुनी जाती है।"},
    {"q":"तीजा का निर्जला व्रत अगले दिन जिस भोजन-रस्म से तोड़ा जाता है, उसे क्या कहते हैं?","o":["फरहार","करू भात","नवाखाई","बासी"],"a":0,"e":"व्रत से पहली रात करू भात खाया जाता है और अगली सुबह \"फरहार\" से व्रत खुलता है।"},
    {"q":"नवरात्रि में देवी की सेवा हेतु टोकरियों में बोए जाने वाले अंकुर क्या कहलाते हैं?","o":["भोजली","जंवारा","सगरी","सोहई"],"a":1,"e":"चैत्र व क्वार नवरात्रि में जंवारा बोकर जस गीत गाए जाते हैं; भोजली श्रावण में बोई जाती है।"},
    {"q":"छत्तीसगढ़ में मितानी (आजीवन मित्रता) बदने के लिए जगन्नाथ के प्रसाद को साक्षी मानकर बनाया गया संबंध क्या कहलाता है?","o":["गंगाजल","दौनापान","महाप्रसाद","जंवारा"],"a":2,"e":"जगन्नाथ के प्रसाद (भात) को साक्षी मानकर बना मित्र \"महापरसाद\" कहलाता है; भोजली, गंगाजल, जंवारा, दौनापान भी मितानी के रूप हैं।"},
    {"q":"रतनपुर के महामाया मंदिर का निर्माण परंपरागत रूप से किस कलचुरि राजा से जोड़ा जाता है?","o":["पृथ्वीदेव द्वितीय","जाजल्लदेव प्रथम","कल्याण साय","रत्नदेव प्रथम"],"a":3,"e":"रतनपुर नगर बसाने वाले कलचुरि राजा रत्नदेव प्रथम (11वीं सदी) से महामाया मंदिर जुड़ा है; रतनपुर कलचुरियों की राजधानी रहा।"},
    {"q":"अंबिकापुर नगर का नाम किस देवी के नाम पर पड़ा माना जाता है?","o":["महामाया (अंबिका)","बम्लेश्वरी","कुदरगढ़ी","समलेश्वरी"],"a":0,"e":"सरगुजा की आराध्य महामाया देवी (अंबिका) के नाम पर अंबिकापुर नाम पड़ा।"},
    {"q":"कुदरगढ़ी (बागेश्वरी) देवी का पहाड़ी मंदिर किस जिले में स्थित है?","o":["जशपुर","सूरजपुर","कोरिया","बलरामपुर"],"a":1,"e":"कुदरगढ़ सूरजपुर जिले में है; यहाँ रामनवमी पर बड़ा मेला लगता है।"},
    {"q":"आरती के समय भालुओं के आने के लिए प्रसिद्ध चंडी माता मंदिर (घुंचापाली) किस जिले में है?","o":["धमतरी","गरियाबंद","महासमुंद","कांकेर"],"a":2,"e":"घुंचापाली, बागबाहरा (महासमुंद) का चंडी मंदिर भालुओं के प्रसाद ग्रहण करने के लिए प्रसिद्ध है।"},
    {"q":"महासमुंद की खल्लारी माता से जुड़ी पौराणिक कथा किससे संबंधित है?","o":["राम-शबरी","कृष्ण-सुदामा","शिव-पार्वती","भीम-हिडिंबा"],"a":3,"e":"खल्लारी (खल्वाटिका) को भीम-हिडिंबा प्रसंग से जोड़ा जाता है; यहाँ \"भीम चूल्हा\" भी है और चैत्र पूर्णिमा पर मेला लगता है।"},
    {"q":"बालोद जिले का \"झलमला\" किस देवी मंदिर के लिए प्रसिद्ध है?","o":["गंगा मैया","महामाया","दंतेश्वरी","शीतला माता"],"a":0,"e":"झलमला का गंगा मैया मंदिर चैत्र व क्वार नवरात्रि मेलों के लिए प्रसिद्ध है।"},
    {"q":"छत्तीसगढ़ में 9 अगस्त (विश्व आदिवासी दिवस) को सामान्य अवकाश पहली बार किस वर्ष घोषित किया गया?","o":["2001","2019","2011","2023"],"a":1,"e":"राज्य शासन ने 9 अगस्त 2019 को विश्व आदिवासी दिवस पर सामान्य अवकाश घोषित किया।"},
    {"q":"राम वन गमन पथ के अंतर्गत छत्तीसगढ़ में श्रीराम के प्रवेश स्थल के रूप में किसे माना जाता है?","o":["रामाराम","चंदखुरी","सीतामढ़ी-हरचौका","तुरतुरिया"],"a":2,"e":"उत्तर में सीतामढ़ी-हरचौका (कोरिया अंचल) प्रवेश स्थल और दक्षिण में रामाराम (सुकमा) अंतिम पड़ाव माना जाता है।"},
    {"q":"सुकमा जिले का \"रामाराम\" किस देवी के मेले के लिए भी प्रसिद्ध है?","o":["मावली","दंतेश्वरी","बम्लेश्वरी","चिटमिटिन अम्मा"],"a":3,"e":"रामाराम में चिटमिटिन अम्मा देवी का मेला लगता है; यह राम वन गमन पथ का दक्षिणी पड़ाव है।"},
    {"q":"छत्तीसगढ़ में \"नुआखाई\" (नवाखाई) मुख्यतः किस राज्य से लगे सीमावर्ती अंचलों में भाद्रपद शुक्ल पंचमी को मनाया जाता है?","o":["ओड़िशा","महाराष्ट्र","झारखंड","मध्य प्रदेश"],"a":0,"e":"नुआखाई पश्चिमी ओड़िशा का प्रमुख पर्व है; रायगढ़, सारंगढ़, महासमुंद जैसे सीमावर्ती अंचलों में इसी रूप में नया अन्न ग्रहण किया जाता है।"},
    {"q":"कबीरपंथ के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. कबीरधाम जिले का नाम कवर्धा की कबीरपंथी गद्दी से जुड़ा है।<br>2. दामाखेड़ा में माघ पूर्णिमा पर संत समागम होता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — कवर्धा धर्मदासी गद्दी का केंद्र रहा।<br>कथन 2 सही — दामाखेड़ा में माघ पूर्णिमा पर विशाल संत समागम/मेला होता है।"},
    {"q":"सूची-I (जनजातीय पर्व) को सूची-II (विशेषता) से सुमेलित कीजिए —<br>(A) सरहुल (B) माटी तिहार (C) करमा (D) भंगाराम जात्रा<br>1. भादो माह में देवताओं की अदालत 2. साल वृक्ष का फूलना 3. करम वृक्ष की डाल की पूजा 4. बीज बोने से पहले धरती माता की पूजा","o":["A-2, B-3, C-4, D-1","A-4, B-2, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1"],"a":3,"e":"सरहुल — साल फूलना (उरांव)।<br>माटी तिहार — बीज बोने से पूर्व धरती पूजा (बस्तर)।<br>करमा — करम डाल।<br>भंगाराम जात्रा — केशकाल में देवताओं की अदालत।"},
    {"q":"देवारी (दीपावली) के निम्नलिखित दिनों को सही क्रम में व्यवस्थित कीजिए —<br>1. गोवर्धन पूजा<br>2. नरक चौदस<br>3. सुरहुत्ती<br>4. धनतेरस","o":["4, 2, 3, 1","2, 4, 3, 1","4, 3, 2, 1","4, 2, 1, 3"],"a":0,"e":"धनतेरस (कृष्ण 13) → नरक चौदस (कृष्ण 14) → सुरहुत्ती (अमावस्या, लक्ष्मी पूजा) → गोवर्धन पूजा (शुक्ल प्रतिपदा)।"},
    {"q":"अभिकथन (A): गोंड समाज की गौरा-गौरी पूजा सुरहुत्ती (दीपावली) की रात होती है।<br>कारण (R): स्त्रियों का सुआ नृत्य गौरा-गौरी विवाह के साथ समाप्त होता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — कार्तिक अमावस्या की रात ईसर-गौरा विवाह होता है।<br>R सही — सुआ गीत-नृत्य का समापन गौरा-गौरी के साथ होता है; पर R, A का कारण नहीं है।"},
    {"q":"बौद्ध स्थलों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. मैनपाट में तिब्बती शरणार्थियों की बस्ती है।<br>2. प्रज्ञागिरि बौद्ध स्थल सिरपुर में स्थित है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — 1962-63 से मैनपाट में तिब्बती बसे हैं।<br>कथन 2 गलत — प्रज्ञागिरि डोंगरगढ़ में है; सिरपुर में आनंदप्रभु कुटी व स्वस्तिक विहार हैं।"},
    {"q":"सूची-I (राम वन गमन पथ का स्थल) को सूची-II (संबद्ध प्रसंग) से सुमेलित कीजिए —<br>(A) चंदखुरी (B) सिहावा (C) तुरतुरिया (D) शिवरीनारायण<br>1. शबरी 2. वाल्मीकि आश्रम 3. शृंगी ऋषि आश्रम 4. माता कौशल्या","o":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-1, B-3, C-2, D-4","A-4, B-3, C-1, D-2"],"a":1,"e":"चंदखुरी — कौशल्या मंदिर।<br>सिहावा — शृंगी ऋषि।<br>तुरतुरिया — वाल्मीकि आश्रम, लव-कुश।<br>शिवरीनारायण — शबरी।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (धार्मिक स्थल — प्रमुख देवालय) सही सुमेलित नहीं है?","o":["खरौद — लक्ष्मणेश्वर","पीथमपुर — कलेश्वरनाथ","राजिम — भोरमदेव","महादेव घाट — हटकेश्वर"],"a":2,"e":"भोरमदेव कबीरधाम में है; राजिम के प्रमुख मंदिर राजीव लोचन व कुलेश्वर महादेव हैं। शेष युग्म सही हैं।"},
    {"q":"राजिम के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. राजिम गरियाबंद जिले में स्थित है।<br>2. कुलेश्वर महादेव मंदिर संगम के मध्य स्थित है।<br>3. राजिम मेला कार्तिक पूर्णिमा से आरंभ होता है।<br>सही कथन हैं —","o":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":0,"e":"कथन 1 सही — राजिम गरियाबंद जिले में है।<br>कथन 2 सही — कुलेश्वर महादेव त्रिवेणी के बीच चबूतरे पर है।<br>कथन 3 गलत — मेला माघ पूर्णिमा से महाशिवरात्रि तक चलता है।"},
    {"q":"अभिकथन (A): कबीरधाम जिले का नाम कबीरपंथ से जुड़ा है।<br>कारण (R): कवर्धा कभी धर्मदासी कबीरपंथ की गद्दी का केंद्र रहा था।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही और R सही — कवर्धा में कबीरपंथ की गद्दी होने के कारण ही जिले का नाम कबीरधाम पड़ा; अतः R, A की सही व्याख्या है।"},
    {"q":"सूची-I (व्यक्ति) को सूची-II (पंथ/परंपरा) से सुमेलित कीजिए —<br>(A) धनी धर्मदास (B) गुरु बालकदास (C) परशुराम भारद्वाज (D) आचार्य विद्यासागर<br>1. रामनामी 2. जैन 3. कबीरपंथ 4. सतनाम पंथ","o":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"a":3,"e":"धनी धर्मदास — कबीरपंथ।<br>गुरु बालकदास (गुरु घासीदास के पुत्र) — सतनाम पंथ।<br>परशुराम भारद्वाज — रामनामी।<br>आचार्य विद्यासागर — दिगंबर जैन।"},
    {"q":"निम्नलिखित को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. गुरु घासीदास विश्वविद्यालय को केंद्रीय दर्जा<br>2. आचार्य विद्यासागर की समाधि<br>3. गहिरा गुरु द्वारा सनातन धर्म संत समाज की स्थापना<br>4. कुनकुरी महागिरजाघर की नींव","o":["3, 1, 4, 2","3, 4, 1, 2","4, 3, 1, 2","3, 4, 2, 1"],"a":1,"e":"संत समाज (1943) → कुनकुरी नींव (1962) → केंद्रीय विश्वविद्यालय (2009) → विद्यासागर समाधि (2024)।"},
    {"q":"हरेली पर कृषि औजारों को भोग के रूप में परंपरागत रूप से कौन-सा व्यंजन चढ़ाया जाता है?","o":["ठेठरी","गुड़ का चीला","खुरमी","फरा"],"a":1,"e":"हरेली पर धुले हुए हल-कुदाल आदि को गुड़ के चीले का भोग लगाया जाता है; ठेठरी-खुरमी तीजा-पोला के व्यंजन हैं।"},
    {"q":"छत्तीसगढ़ में दशहरे के दिन एक-दूसरे को शुभकामना के रूप में कौन-सी वस्तु भेंट की जाती है?","o":["नारियल","जंवारा","सोनपत्ती","भोजली"],"a":2,"e":"दशहरे पर \"सोनपत्ती\" (स्वर्ण का प्रतीक पत्ता) देकर बड़ों का आशीर्वाद लिया जाता है।"},
    {"q":"सरगुजा-कोरिया अंचल में ज्येष्ठ शुक्ल दशमी को मेलों के साथ मनाया जाने वाला पर्व कौन-सा है?","o":["छेरछेरा","अक्ती","करमा","गंगा दशहरा"],"a":3,"e":"गंगा दशहरा पर उत्तरी छत्तीसगढ़ में कई स्थानों पर मेले लगते हैं और \"दशहरा\" गीत गाए जाते हैं।"},
    {"q":"मल्हार (बिलासपुर) का कौन-सा प्राचीन देवी मंदिर कलचुरियों से संबद्ध है?","o":["डिडिनेश्वरी देवी","बम्लेश्वरी","चंद्रहासिनी","मावली"],"a":0,"e":"मल्हार में डिडिनेश्वरी देवी और पातालेश्वर (केदारेश्वर) मंदिर प्रसिद्ध हैं; यहाँ बौद्ध-जैन अवशेष भी मिले हैं।"},
    {"q":"ताला (बिलासपुर) के प्रसिद्ध मंदिर-युगल का नाम क्या है?","o":["मामा-भांजा","देवरानी-जेठानी","बत्तीसा","मड़वा-छेरकी"],"a":1,"e":"मनियारी नदी तट पर ताला के देवरानी-जेठानी मंदिर और रुद्र शिव प्रतिमा प्रसिद्ध हैं; मामा-भांजा व बत्तीसा मंदिर बारसूर में हैं।"},
    {"q":"दंतेवाड़ा जिले में बैलाडीला की पहाड़ी पर लगभग 3000 फीट ऊँचाई पर स्थित प्रसिद्ध गणेश प्रतिमा कौन-सी है?","o":["बारसूर गणेश","चित्रकोट गणेश","ढोलकल गणेश","नारायणपाल गणेश"],"a":2,"e":"ढोलकल शिखर पर स्थित गणेश प्रतिमा नागवंशी काल की मानी जाती है; बारसूर में जुड़वाँ विशाल गणेश प्रतिमाएँ अलग हैं।"},
    {"q":"बारसूर (दंतेवाड़ा) निम्न में से किस मंदिर के लिए प्रसिद्ध है?","o":["भांड देवल","लक्ष्मणेश्वर","देवरानी-जेठानी","बत्तीसा मंदिर"],"a":3,"e":"बारसूर में बत्तीसा (32 स्तंभों वाला) मंदिर, मामा-भांजा मंदिर और विशाल गणेश प्रतिमाएँ हैं।"},
    {"q":"जांजगीर का प्रसिद्ध अधूरा विष्णु मंदिर लोक में किस नाम से जाना जाता है?","o":["नकटा मंदिर","मड़वा महल","छेरकी महल","भांड देवल"],"a":0,"e":"जांजगीर का कलचुरि कालीन विष्णु मंदिर शिखर-विहीन (अधूरा) होने से \"नकटा मंदिर\" कहलाता है।"},
    {"q":"\"मंदिरों की नगरी\" कहे जाने वाले आरंग को किस पौराणिक राजा की कथा से जोड़ा जाता है?","o":["राजा हरिश्चंद्र","राजा मोरध्वज","राजा नल","राजा भर्तृहरि"],"a":1,"e":"आरंग को राजा मोरध्वज की नगरी माना जाता है (आरा से पुत्र को चीरने की कथा से \"आरंग\" नाम); यहीं जैन भांड देवल भी है।"},
    {"q":"बलौदाबाजार जिले के पलारी में स्थित ईंटों से निर्मित प्राचीन शिव मंदिर कौन-सा है?","o":["हटकेश्वर","गंधेश्वर","सिद्धेश्वर","कलेश्वरनाथ"],"a":2,"e":"पलारी का सिद्धेश्वर मंदिर ईंटों से बना है; गंधेश्वर सिरपुर में और हटकेश्वर रायपुर में है।"},
    {"q":"संत गहिरा गुरु से संबद्ध \"कैलाश गुफा\" किस जिले में स्थित है?","o":["कोरिया","बलरामपुर","सूरजपुर","जशपुर"],"a":3,"e":"कैलाश गुफा जशपुर जिले (बगीचा क्षेत्र) में है, जिसे गहिरा गुरु ने आश्रम-स्थल बनाया; यहाँ महाशिवरात्रि पर मेला लगता है।"},
    {"q":"गुरु घासीदास द्वारा उपदेश के लिए की गई यात्राओं के पड़ावों को सतनामी परंपरा में क्या कहा जाता है?","o":["रावटी","चौका","मड़ई","जात्रा"],"a":0,"e":"गुरु घासीदास ने विभिन्न स्थानों पर \"रावटी\" (प्रवचन-शिविर) लगाकर सतनाम का प्रचार किया; चौका कबीरपंथ की आरती-विधि है।"},
    {"q":"गुरु घासीदास के उत्तराधिकारी के रूप में सतनाम पंथ का नेतृत्व किसने संभाला?","o":["गुरु अमरदास","गुरु बालकदास","मिनीमाता","परशुराम भारद्वाज"],"a":1,"e":"गुरु घासीदास के बाद उनके पुत्र गुरु बालकदास ने पंथ का नेतृत्व किया और प्रचार को आगे बढ़ाया।"},
    {"q":"हसदेव नदी पर बने बांगो बाँध के जलाशय का नाम किस सतनामी समाजसेवी व सांसद के नाम पर है?","o":["सफुरा माता","राजमाता फुलकैना","मिनीमाता","माता कर्मा"],"a":2,"e":"मिनीमाता छत्तीसगढ़ की प्रथम महिला सांसद थीं; \"मिनीमाता बांगो जलाशय\" और राज्य का मिनीमाता सम्मान उनके नाम पर हैं।"},
    {"q":"स्वामी आत्मानंद द्वारा अबूझमाड़ क्षेत्र में स्थापित रामकृष्ण मिशन आश्रम कहाँ है?","o":["जगदलपुर","कोंडागांव","दंतेवाड़ा","नारायणपुर"],"a":3,"e":"स्वामी आत्मानंद ने 1985 में नारायणपुर में रामकृष्ण मिशन आश्रम स्थापित किया; रायपुर का विवेकानंद आश्रम भी उन्हीं की देन है।"},
    {"q":"भावातीत ध्यान (ट्रांसेंडेंटल मेडिटेशन) के प्रणेता महर्षि महेश योगी का जन्म छत्तीसगढ़ के किस स्थान पर हुआ था?","o":["पांडुका","राजिम","चंपारण","आरंग"],"a":0,"e":"महर्षि महेश योगी का जन्म 1918 में पांडुका (वर्तमान गरियाबंद जिला) में हुआ था।"},
    {"q":"वल्लभाचार्य की \"प्राकट्य बैठक\" किस स्थान पर है?","o":["राजिम","चंपारण","सिरपुर","शिवरीनारायण"],"a":1,"e":"चंपारण में वल्लभाचार्य की प्राकट्य (जन्म) बैठक है; पुष्टिमार्ग में उनकी 84 बैठकें मान्य हैं।"},
    {"q":"बस्तर दशहरा में माँ दंतेश्वरी का कौन-सा रूप दंतेवाड़ा से डोली में जगदलपुर लाया जाता है?","o":["काछन देवी","रैला देवी","मावली माता","हिंगलाजिन"],"a":2,"e":"नवमी को मावली परघाव में मावली माता (दंतेश्वरी) की डोली और छत्र का स्वागत होता है; काछन देवी अमावस्या की रस्म से जुड़ी हैं।"},
    {"q":"बस्तर दशहरा में बस्तर के विभिन्न परगनों से आए ग्राम देवी-देवताओं की ससम्मान विदाई की रस्म क्या कहलाती है?","o":["ओहाड़ी","निशा जात्रा","मावली परघाव","कुटुंब जात्रा"],"a":3,"e":"कुटुंब जात्रा में आमंत्रित सैकड़ों ग्राम देवी-देवताओं को भेंट देकर विदा किया जाता है; ओहाड़ी में माँ दंतेश्वरी की डोली विदा होती है।"},
    {"q":"निशा जात्रा की रस्म जिस मंदिर में होती है, उसकी विशेषता क्या है?","o":["वर्ष में केवल एक बार खुलता है","नदी के बीच स्थित है","पहाड़ी की चोटी पर है","वहाँ केवल महिलाएँ जाती हैं"],"a":0,"e":"जगदलपुर का निशागुड़ी मंदिर वर्ष में केवल एक बार, अष्टमी की रात निशा जात्रा के लिए खुलता है।"},
    {"q":"राउत समाज का मातर पर्व परंपरागत रूप से गाँव के किस स्थल पर मनाया जाता है?","o":["सरना","दईहान (गौठान)","घोटुल","सिरासार"],"a":1,"e":"मातर गाँव के दईहान (पशु-एकत्र होने के स्थान) में खोड़हर देव की स्थापना कर मनाया जाता है; सरना उरांव का पूजा-स्थल है।"},
    {"q":"दीपावली के बाद राउत समाज द्वारा गायों को सोहई बाँधने के बदले मालिक से मिलने वाली भेंट का आधार क्या है?","o":["सरकारी अनुदान","मंदिर का दान","पशुपालक-कृषक का परंपरागत सेवा-संबंध","मेला कर"],"a":2,"e":"राउत वर्षभर किसानों के पशु चराते हैं; सोहई बाँधकर वे आशीष देते हैं और बदले में अन्न-वस्त्र पाते हैं — यह ग्रामीण सेवा-संबंध का प्रतीक है।"},
    {"q":"अगहन बिरस्पत, तीजा और कमरछठ — इन तीनों में क्या समानता है?","o":["तीनों पुरुषों द्वारा मनाए जाते हैं","तीनों पूर्णिमा को पड़ते हैं","तीनों जनजातीय पर्व हैं","तीनों मुख्यतः स्त्रियों के व्रत हैं"],"a":3,"e":"अगहन बिरस्पत (लक्ष्मी), तीजा (पति की दीर्घायु) और कमरछठ (संतान की दीर्घायु) — तीनों स्त्रियों के व्रत हैं; इनमें कोई भी पूर्णिमा को नहीं पड़ता।"},
    {"q":"सूची-I (स्थल) को सूची-II (प्रसिद्ध मंदिर) से सुमेलित कीजिए —<br>(A) ताला (B) बारसूर (C) जांजगीर (D) पलारी<br>1. नकटा मंदिर 2. सिद्धेश्वर मंदिर 3. देवरानी-जेठानी 4. मामा-भांजा","o":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"a":3,"e":"ताला — देवरानी-जेठानी।<br>बारसूर — मामा-भांजा।<br>जांजगीर — नकटा (विष्णु) मंदिर।<br>पलारी — सिद्धेश्वर मंदिर।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. ढोलकल गणेश दंतेवाड़ा जिले की बैलाडीला पहाड़ी पर स्थित हैं।<br>2. बत्तीसा मंदिर ताला में स्थित है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — ढोलकल शिखर बैलाडीला श्रेणी में है।<br>कथन 2 गलत — बत्तीसा मंदिर बारसूर में है; ताला में देवरानी-जेठानी मंदिर हैं।"},
    {"q":"अभिकथन (A): जांजगीर का विष्णु मंदिर \"नकटा मंदिर\" कहलाता है।<br>कारण (R): इस मंदिर का शिखर कभी पूरा नहीं बन सका।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही — लोक में इसे नकटा मंदिर कहते हैं।<br>R सही और व्याख्या — शिखर-विहीन (अधूरा) होने के कारण ही यह नाम पड़ा।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (संत/व्यक्ति — संबद्ध संस्था/स्थल) सही सुमेलित नहीं है?","o":["स्वामी आत्मानंद — रामकृष्ण मिशन आश्रम, नारायणपुर","महर्षि महेश योगी — पांडुका","गहिरा गुरु — कैलाश गुफा","महंत बलभद्र दास — दामाखेड़ा"],"a":3,"e":"महंत बलभद्र दास रायपुर के दूधाधारी मठ से जुड़े हैं; दामाखेड़ा कबीरपंथ की गद्दी है। शेष युग्म सही हैं।"},
    {"q":"सतनाम पंथ के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. गुरु घासीदास के बाद गुरु बालकदास ने पंथ का नेतृत्व किया।<br>2. गुरु घासीदास ने उपदेश हेतु \"रावटी\" लगाई।<br>3. सतनाम पंथ में मांसाहार व नशे का निषेध है।<br>सही कथन हैं —","o":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":3,"e":"कथन 1 सही — बालकदास उत्तराधिकारी बने।<br>कथन 2 सही — रावटी उनके प्रवचन-पड़ाव थे।<br>कथन 3 सही — मांस-मदिरा व नशा निषेध सात सिद्धांतों में है।"},
    {"q":"अभिकथन (A): गुरु घासीदास ने दोपहर में हल न चलाने का उपदेश दिया।<br>कारण (R): गुरु घासीदास पशुओं के प्रति दया और जीव-कल्याण पर बल देते थे।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही — यह सात सिद्धांतों में शामिल है।<br>R सही और व्याख्या — दोपहर की तपती धूप में बैलों को कष्ट न हो, इसी दया-भाव से यह नियम बना।"},
    {"q":"सूची-I (बस्तर दशहरा का पात्र/वस्तु) को सूची-II (संबद्ध रस्म) से सुमेलित कीजिए —<br>(A) ठुरलू खोटला (B) हल्बा जाति का जोगी (C) मावली की डोली (D) मांझी-चालकी<br>1. मुरिया दरबार 2. पाट जात्रा 3. मावली परघाव 4. जोगी बिठाई","o":["A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-1, D-3"],"a":0,"e":"ठुरलू खोटला — पाट जात्रा।<br>हल्बा जोगी — जोगी बिठाई।<br>मावली की डोली — मावली परघाव।<br>मांझी-चालकी — मुरिया दरबार।"},
    {"q":"बस्तर दशहरा के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. प्रथम मुरिया दरबार 8 मार्च 1876 को हुआ था।<br>2. मुरिया दरबार कुम्हड़ाकोट के जंगल में आयोजित होता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — सिरोंचा के डिप्टी कमिश्नर द्वारा मांझी-चालकियों को संबोधन।<br>कथन 2 गलत — मुरिया दरबार सिरासार भवन में होता है।"},
    {"q":"अभिकथन (A): बस्तर दशहरा में भीतर रैनी की रात विजय रथ को माड़िया लोग \"चुराकर\" कुम्हड़ाकोट ले जाते हैं।<br>कारण (R): बाहर रैनी के दिन राजा कुम्हड़ाकोट जाकर नवाखानी करते हैं और रथ वापस लाया जाता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — दशमी की रात रथ \"चोरी\" की रस्म होती है।<br>R सही — एकादशी को रथ वापस आता है; पर यह अगली रस्म का वर्णन है, A का कारण नहीं।"},
    {"q":"बस्तर दशहरा की निम्नलिखित रस्मों को सही क्रम में व्यवस्थित कीजिए —<br>1. कुटुंब जात्रा<br>2. पाट जात्रा<br>3. कलश स्थापना<br>4. बाहर रैनी","o":["2, 4, 3, 1","2, 3, 1, 4","3, 2, 4, 1","2, 3, 4, 1"],"a":3,"e":"पाट जात्रा (श्रावण अमावस्या) → कलश स्थापना (आश्विन शुक्ल प्रतिपदा) → बाहर रैनी (एकादशी) → कुटुंब जात्रा (विदाई)।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (बस्तर दशहरा — स्थल) सही सुमेलित नहीं है?","o":["बेल पूजा — सरगीपाल","जोगी बिठाई — सिरासार भवन","निशा जात्रा — निशागुड़ी","पाट जात्रा — कुम्हड़ाकोट"],"a":3,"e":"पाट जात्रा दंतेश्वरी मंदिर (जगदलपुर) के सामने होती है; कुम्हड़ाकोट भीतर/बाहर रैनी से जुड़ा है। शेष युग्म सही हैं।"},
    {"q":"सूची-I (पर्व) को सूची-II (विशेष व्यंजन/भोग) से सुमेलित कीजिए —<br>(A) हरेली (B) कमरछठ (C) तीजा (पूर्व संध्या) (D) गोवर्धन पूजा (पशुओं हेतु)<br>1. करू भात 2. खिचड़ी 3. गुड़ का चीला 4. पसहर चावल","o":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2"],"a":2,"e":"हरेली — गुड़ चीला।<br>कमरछठ — पसहर चावल।<br>तीजा की पूर्व संध्या — करू भात।<br>गोवर्धन पूजा — पशुओं को खिचड़ी।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. सरहुल पर्व की पूजा \"सरना\" स्थल पर \"पाहन\" द्वारा कराई जाती है।<br>2. करमा पर्व में करमसेनी देवी की पूजा होती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — उरांव का पुजारी पाहन और पूजा-स्थल सरना है।<br>कथन 2 सही — करम डाल के साथ करमसेनी देवी पूजी जाती हैं।"},
    {"q":"अभिकथन (A): भोजली पर्व मुख्यतः श्रावण माह में मनाया जाता है।<br>कारण (R): भोजली में धान के अंकुर उगाए जाते हैं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही — भोजली श्रावण शुक्ल पक्ष में बोई और रक्षाबंधन के अगले दिन विसर्जित होती है।<br>R गलत — भोजली गेहूँ के अंकुरों से बनती है।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (मितानी का प्रकार — साक्षी) सही सुमेलित नहीं है?","o":["महाप्रसाद — जगन्नाथ का प्रसाद","भोजली — गेहूँ के अंकुर","गंगाजल — गंगा का जल","जंवारा — करम वृक्ष की डाल"],"a":3,"e":"जंवारा नवरात्रि में बोए अंकुर हैं; करम डाल करमा पर्व से जुड़ी है। शेष तीनों युग्म सही हैं।"},
    {"q":"सूची-I (धार्मिक व्यक्तित्व) को सूची-II (विवरण) से सुमेलित कीजिए —<br>(A) स्वामी विवेकानंद (B) स्वामी आत्मानंद (C) महर्षि महेश योगी (D) मिनीमाता<br>1. भावातीत ध्यान 2. किशोरावस्था में रायपुर-प्रवास 3. प्रथम महिला सांसद (छत्तीसगढ़) 4. नारायणपुर आश्रम","o":["A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3"],"a":1,"e":"विवेकानंद — रायपुर प्रवास (1877–79)।<br>आत्मानंद — नारायणपुर रामकृष्ण मिशन आश्रम।<br>महेश योगी — भावातीत ध्यान।<br>मिनीमाता — प्रथम महिला सांसद।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. वल्लभाचार्य का जन्म वैशाख कृष्ण एकादशी को हुआ था।<br>2. पुष्टिमार्ग में वल्लभाचार्य की 84 बैठकें मानी जाती हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — इसी तिथि को चंपारण में जयंती-उत्सव होता है।<br>कथन 2 सही — देशभर में उनकी 84 बैठकें हैं, जिनमें चंपारण प्राकट्य बैठक है।"},
    {"q":"निम्नलिखित स्थलों को उत्तर से दक्षिण के क्रम में व्यवस्थित कीजिए (राम वन गमन पथ) —<br>1. चंदखुरी<br>2. सीतामढ़ी-हरचौका<br>3. रामाराम<br>4. शिवरीनारायण","o":["2, 1, 4, 3","2, 4, 3, 1","4, 2, 1, 3","2, 4, 1, 3"],"a":3,"e":"सीतामढ़ी-हरचौका (कोरिया अंचल, उत्तर) → शिवरीनारायण (जांजगीर-चांपा) → चंदखुरी (रायपुर) → रामाराम (सुकमा, दक्षिण)।"},
    {"q":"अभिकथन (A): अंबिकापुर का नाम देवी महामाया (अंबिका) से जुड़ा है।<br>कारण (R): महामाया सरगुजा अंचल की आराध्य देवी हैं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही और R सही — सरगुजा की आराध्य देवी अंबिका (महामाया) के नाम पर ही नगर का नाम पड़ा; अतः R, A की व्याख्या है।"},
    {"q":"सूची-I (देवी) को सूची-II (जिला) से सुमेलित कीजिए —<br>(A) कुदरगढ़ी (B) अंगारमोती (C) गंगा मैया, झलमला (D) डिडिनेश्वरी<br>1. बिलासपुर 2. बालोद 3. धमतरी 4. सूरजपुर","o":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"a":0,"e":"कुदरगढ़ी — सूरजपुर।<br>अंगारमोती — धमतरी (गंगरेल)।<br>गंगा मैया — बालोद (झलमला)।<br>डिडिनेश्वरी — बिलासपुर (मल्हार)।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. रतनपुर का महामाया मंदिर शक्तिपीठ माना जाता है।<br>2. दंतेवाड़ा की दंतेश्वरी शक्तिपीठ से सती के दाँत गिरने की मान्यता जुड़ी है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — रतनपुर में सती का स्कंध गिरने की मान्यता है।<br>कथन 2 सही — \"दंतेश्वरी\" नाम ही दाँत गिरने की कथा से जुड़ा है।"},
    {"q":"छत्तीसगढ़ में \"दियारी\" पर्व मुख्यतः किस अंचल में मनाया जाता है?","o":["सरगुजा","बस्तर","मैदानी रायपुर","कबीरधाम"],"a":1,"e":"दियारी बस्तर का जनजातीय दीपावली-रूप है — पशुधन की पूजा, खिचड़ी खिलाना और नई फसल का उत्सव।"},
    {"q":"बस्तर का \"माटी तिहार\" वर्ष के किस समय मनाया जाता है?","o":["कार्तिक में फसल कटाई के बाद","पौष में","चैत्र में बीज बोने से पहले","भाद्रपद में"],"a":2,"e":"चैत्र माह में बीज बोने से पहले धरती माता की पूजा होती है; इस दिन भूमि खोदना वर्जित माना जाता है।"},
    {"q":"\"छत्तीसगढ़ की काशी\" के नाम से कौन-सा स्थान प्रसिद्ध है?","o":["राजिम","खरौद","रतनपुर","सिरपुर"],"a":1,"e":"खरौद (जांजगीर-चांपा) अनेक शिव मंदिरों, विशेषकर लक्ष्मणेश्वर, के कारण \"छत्तीसगढ़ की काशी\" कहलाता है; राजिम \"छत्तीसगढ़ का प्रयाग\" है।"},
    {"q":"छत्तीसगढ़ का पहला ईसाई मिशन कहाँ स्थापित हुआ?","o":["कुनकुरी","जशपुर","बिश्रामपुर","मलखरौदा"],"a":2,"e":"1868 में रेव. ऑस्कर लोर ने बिश्रामपुर में मिशन स्थापित किया; यहीं 1873 में क्षेत्र का पहला चर्च बना।"},
    {"q":"कुनकुरी का \"रोज़री की महारानी\" महागिरजाघर किस रूप में प्रसिद्ध है?","o":["भारत का सबसे पुराना चर्च","विश्व का सबसे बड़ा चर्च","छत्तीसगढ़ का एकमात्र चर्च","एशिया का दूसरा सबसे बड़ा चर्च"],"a":3,"e":"कुनकुरी (जशपुर) का कैथोलिक महागिरजाघर एशिया का दूसरा सबसे बड़ा चर्च माना जाता है; लोकार्पण 27 अक्टूबर 1979।"},
    {"q":"कबीरपंथी अनुयायी परस्पर अभिवादन में प्रायः क्या कहते हैं?","o":["साहेब बंदगी","जय सतनाम","जय जोहार","राम-राम"],"a":0,"e":"\"साहेब बंदगी\" कबीरपंथ का पारंपरिक अभिवादन है; \"जय जोहार\" सामान्य छत्तीसगढ़ी अभिवादन है।"},
    {"q":"कबीरपंथ का प्रमुख तीर्थ दामाखेड़ा किस कस्बे के निकट स्थित है?","o":["भाटापारा","सिमगा","कवर्धा","तिल्दा"],"a":1,"e":"दामाखेड़ा बलौदाबाजार-भाटापारा जिले में सिमगा के निकट है।"},
    {"q":"राजिम पंचकोसी यात्रा के \"फणिकेश्वर महादेव\" किस स्थान पर हैं?","o":["पटेवा","बम्हनी","फिंगेश्वर","कोपरा"],"a":2,"e":"फणिकेश्वर — फिंगेश्वर; पटेश्वर — पटेवा; ब्रह्मनेश्वर — बम्हनी; कर्पूरेश्वर — कोपरा; चंपकेश्वर — चंपारण।"},
    {"q":"चंद्रपुर की चंद्रहासिनी देवी का मंदिर किन नदियों के संगम पर है?","o":["महानदी-शिवनाथ","इंद्रावती-नारंगी","शंखिनी-डंकिनी","महानदी-मांड"],"a":3,"e":"चंद्रहासिनी मंदिर महानदी और मांड के संगम पर है; शंखिनी-डंकिनी संगम पर दंतेश्वरी मंदिर है।"},
    {"q":"डोंगरगढ़ में पहाड़ी के नीचे स्थित देवी मंदिर को क्या कहा जाता है?","o":["छोटी बम्लेश्वरी","बड़ी बम्लेश्वरी","प्रज्ञागिरि","चंद्रगिरि"],"a":0,"e":"पहाड़ी (लगभग 1600 फीट) पर बड़ी बम्लेश्वरी और नीचे छोटी बम्लेश्वरी का मंदिर है।"},
    {"q":"छत्तीसगढ़ का राज्य स्थापना दिवस (राज्योत्सव) कब मनाया जाता है?","o":["26 जनवरी","1 नवंबर","15 अगस्त","28 नवंबर"],"a":1,"e":"1 नवंबर 2000 को छत्तीसगढ़ राज्य बना; इसी दिन राज्योत्सव व राज्य अलंकरण समारोह होते हैं। 28 नवंबर छत्तीसगढ़ी राजभाषा दिवस है।"},
    {"q":"10 फरवरी को मनाया जाने वाला \"भूमकाल स्मृति दिवस\" किस जननायक से जुड़ा है?","o":["वीर नारायण सिंह","गेंद सिंह","गुंडाधुर","हनुमान सिंह"],"a":2,"e":"1910 के बस्तर भूमकाल विद्रोह के नायक गुंडाधुर थे; गेंद सिंह परलकोट विद्रोह (1825) से जुड़े हैं।"},
    {"q":"\"छत्तीसगढ़ के गांधी\" कहे जाने वाले पं. सुंदरलाल शर्मा की जयंती कब मनाई जाती है?","o":["10 दिसंबर","18 दिसंबर","2 अक्टूबर","21 दिसंबर"],"a":3,"e":"पं. सुंदरलाल शर्मा का जन्म 21 दिसंबर 1881 को हुआ; 18 दिसंबर गुरु घासीदास जयंती और 10 दिसंबर वीर नारायण सिंह बलिदान दिवस है।"},
    {"q":"शहीद वीर नारायण सिंह को 10 दिसंबर 1857 को रायपुर में जिस स्थान पर फाँसी दी गई, वह आज किस नाम से जाना जाता है?","o":["जयस्तंभ चौक","गोल बाज़ार","कालीबाड़ी चौक","आज़ाद चौक"],"a":0,"e":"रायपुर का जयस्तंभ चौक वीर नारायण सिंह के बलिदान-स्थल के रूप में प्रसिद्ध है; 10 दिसंबर बलिदान दिवस है।"},
    {"q":"उरांव जनजाति का सरहुल पर्व किस माह में मनाया जाता है?","o":["कार्तिक","चैत्र","भाद्रपद","पौष"],"a":1,"e":"सरहुल चैत्र माह में साल वृक्ष के फूलने पर मनाया जाता है; यह नववर्ष व प्रकृति-पूजा का पर्व है।"},
    {"q":"करमा पर्व के साथ परंपरागत रूप से कौन-सी कथा सुनी जाती है?","o":["सत्यनारायण कथा","लोरिक-चंदा","करमा-धरमा भाइयों की कथा","भरथरी कथा"],"a":2,"e":"करमा की रात करम डाल के सामने करमा-धरमा दो भाइयों की कथा सुनी जाती है, जिसमें कर्म (परिश्रम) का महत्व बताया गया है।"},
    {"q":"गोंचा पर्व की \"हेरा पंचमी\" रस्म किस प्रसंग से संबंधित है?","o":["भगवान का स्नान","रथ का निर्माण","भगवान की वापसी","देवी लक्ष्मी द्वारा भगवान जगन्नाथ को खोजने जाना"],"a":3,"e":"हेरा (खोजना) पंचमी पर लक्ष्मी जी जगन्नाथ को खोजने गुंडिचा मंदिर जाती हैं; वापसी \"बाहुड़ा\" कहलाती है।"},
    {"q":"गोंचा पर्व के आरंभ में भगवान जगन्नाथ, बलभद्र व सुभद्रा के स्नान की रस्म क्या कहलाती है?","o":["चंदन जात्रा","नेत्रोत्सव","हेरा पंचमी","अनसर"],"a":0,"e":"चंदन जात्रा (स्नान) के बाद भगवान \"अनसर काल\" में विश्राम करते हैं, फिर नेत्रोत्सव होता है।"},
    {"q":"कबीरधाम जिले में प्रतिवर्ष आयोजित होने वाला प्रसिद्ध महोत्सव कौन-सा है?","o":["सिरपुर महोत्सव","भोरमदेव महोत्सव","चक्रधर समारोह","रामगढ़ महोत्सव"],"a":1,"e":"भोरमदेव महोत्सव कबीरधाम में (चैत्र के आसपास) होता है; चक्रधर समारोह रायगढ़ और रामगढ़ महोत्सव सरगुजा में।"},
    {"q":"रतनपुर के महामाया मंदिर में नवरात्रि पर कौन-सी परंपरा विशेष रूप से प्रसिद्ध है?","o":["रथयात्रा","काछन गादी","हज़ारों मनोकामना ज्योति कलश","तुपकी चलाना"],"a":2,"e":"चैत्र व क्वार नवरात्रि में रतनपुर में हज़ारों ज्योति कलश जलाए जाते हैं; माघ पूर्णिमा पर मेला भी लगता है।"},
    {"q":"जैतखाम पर लगाया जाने वाला सफेद ध्वज किसका प्रतीक माना जाता है?","o":["विजय और शौर्य","वैराग्य और त्याग","समृद्धि","सत्य और शांति"],"a":3,"e":"सतनाम पंथ में सफेद ध्वज सत्य (सतनाम) और शांति का प्रतीक है।"},
    {"q":"निम्नलिखित पर्वों को कार्तिक से आरंभ करते हुए वर्ष में आने के क्रम में व्यवस्थित कीजिए —<br>1. जेठौनी<br>2. छेरछेरा<br>3. सुरहुत्ती<br>4. अगहन बिरस्पत","o":["3, 1, 4, 2","1, 3, 4, 2","3, 4, 1, 2","3, 1, 2, 4"],"a":0,"e":"सुरहुत्ती (कार्तिक अमावस्या) → जेठौनी (कार्तिक शुक्ल 11) → अगहन बिरस्पत (मार्गशीर्ष के गुरुवार) → छेरछेरा (पौष पूर्णिमा)।"},
    {"q":"चैत्र से आरंभ करते हुए निम्नलिखित को वर्ष में आने के क्रम में व्यवस्थित कीजिए —<br>1. माता कर्मा जयंती<br>2. वल्लभाचार्य जयंती<br>3. गंगा दशहरा<br>4. अक्ती","o":["1, 4, 2, 3","1, 2, 4, 3","2, 1, 4, 3","1, 2, 3, 4"],"a":1,"e":"माता कर्मा जयंती (चैत्र कृष्ण 11) → वल्लभाचार्य जयंती (वैशाख कृष्ण 11) → अक्ती (वैशाख शुक्ल 3) → गंगा दशहरा (ज्येष्ठ शुक्ल 10)।"},
    {"q":"कार्तिक से आरंभ करते हुए निम्नलिखित मेलों को वर्ष में आने के क्रम में व्यवस्थित कीजिए —<br>1. गिरौदपुरी मेला<br>2. तुरतुरिया मेला<br>3. महादेव घाट मेला<br>4. राजिम माघी पुन्नी मेला","o":["3, 4, 2, 1","2, 3, 4, 1","3, 2, 4, 1","3, 2, 1, 4"],"a":2,"e":"महादेव घाट (कार्तिक पूर्णिमा) → तुरतुरिया (पौष पूर्णिमा) → राजिम (माघ पूर्णिमा से) → गिरौदपुरी (फाल्गुन शुक्ल 5)।"},
    {"q":"सूची-I (उपनाम) को सूची-II (स्थान) से सुमेलित कीजिए —<br>(A) छत्तीसगढ़ की काशी (B) छत्तीसगढ़ की जगन्नाथपुरी (C) छत्तीसगढ़ का प्रयाग (D) मिनी तिब्बत<br>1. मैनपाट 2. राजिम 3. शिवरीनारायण 4. खरौद","o":["A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1"],"a":3,"e":"खरौद — छत्तीसगढ़ की काशी।<br>शिवरीनारायण — जगन्नाथपुरी।<br>राजिम — प्रयाग।<br>मैनपाट — मिनी तिब्बत।"},
    {"q":"सूची-I (तीर्थ) को सूची-II (पंथ/परंपरा) से सुमेलित कीजिए —<br>(A) गिरौदपुरी (B) दामाखेड़ा (C) चंपारण (D) चारपारा<br>1. कबीरपंथ 2. सतनाम पंथ 3. रामनामी 4. पुष्टिमार्ग (वल्लभाचार्य)","o":["A-2, B-1, C-4, D-3","A-1, B-2, C-4, D-3","A-2, B-1, C-3, D-4","A-2, B-4, C-1, D-3"],"a":0,"e":"गिरौदपुरी — सतनाम।<br>दामाखेड़ा — कबीरपंथ।<br>चंपारण — वल्लभाचार्य (पुष्टिमार्ग)।<br>चारपारा — रामनामी।"},
    {"q":"सूची-I (स्थल) को सूची-II (विशेषता) से सुमेलित कीजिए —<br>(A) कुनकुरी (B) बिश्रामपुर (C) लुतरा शरीफ (D) मदकू द्वीप<br>1. 1868 का मिशन 2. शिवनाथ द्वीप पर ईसाई मेला 3. महागिरजाघर 4. सूफी दरगाह","o":["A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2"],"a":1,"e":"कुनकुरी — महागिरजाघर।<br>बिश्रामपुर — 1868 का प्रथम मिशन।<br>लुतरा शरीफ — बाबा सैयद इंसान अली शाह की दरगाह।<br>मदकू द्वीप — ईसाई मेला।"},
    {"q":"सूची-I (गोंचा की रस्म) को सूची-II (अर्थ) से सुमेलित कीजिए —<br>(A) चंदन जात्रा (B) नेत्रोत्सव (C) हेरा पंचमी (D) बाहुड़ा गोंचा<br>1. वापसी यात्रा 2. देव-स्नान 3. लक्ष्मी द्वारा जगन्नाथ की खोज 4. नेत्र-अनुष्ठान","o":["A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3"],"a":2,"e":"चंदन जात्रा — स्नान।<br>नेत्रोत्सव — नेत्र-अनुष्ठान।<br>हेरा पंचमी — लक्ष्मी की खोज।<br>बाहुड़ा — वापसी।"},
    {"q":"छेरछेरा के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. इस दिन युवक डंडा नाच करते हुए घर-घर जाते हैं।<br>2. \"अरन बरन कोदो दरन, जभे देबे तभे टरन\" इसी पर्व से जुड़ी पंक्ति है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — छेरछेरा पर डंडा (शैला) नाच होता है।<br>कथन 2 सही — \"जब तक दोगे नहीं, तब तक हटेंगे नहीं\" भाव वाली यह पंक्ति दान माँगते समय बोली जाती है।"},
    {"q":"गोवर्धन पूजा के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. यह कार्तिक शुक्ल प्रतिपदा को मनाई जाती है।<br>2. इस दिन गायों के गले में सोहई गोंड समाज के लोग बाँधते हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — दीपावली के अगले दिन गोवर्धन पूजा होती है।<br>कथन 2 गलत — सोहई राउत (यादव) समाज बाँधता है।"},
    {"q":"जैन स्थलों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. नगपुरा का पार्श्व तीर्थ खारुन नदी के तट पर है।<br>2. आरंग का भांड देवल एक जैन मंदिर है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — नगपुरा (दुर्ग) शिवनाथ नदी के तट पर है।<br>कथन 2 सही — भांड देवल 11वीं सदी का जैन मंदिर है जिसमें तीन तीर्थंकर प्रतिमाएँ हैं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. स्वामी विवेकानंद 1877–79 के बीच रायपुर में रहे।<br>2. रायपुर के बूढ़ा तालाब का नाम अब विवेकानंद सरोवर है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — किशोर नरेंद्र अपने पिता के साथ लगभग दो वर्ष रायपुर में रहे।<br>कथन 2 सही — बूढ़ा तालाब को विवेकानंद सरोवर नाम दिया गया।"},
    {"q":"प्रतीक दिवसों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. 10 फरवरी को भूमकाल स्मृति दिवस मनाया जाता है।<br>2. 18 दिसंबर पं. सुंदरलाल शर्मा की जयंती है।<br>3. 10 दिसंबर शहीद वीर नारायण सिंह का बलिदान दिवस है।<br>सही कथन हैं —","o":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":2,"e":"कथन 1 सही — 1910 का भूमकाल।<br>कथन 2 गलत — 18 दिसंबर गुरु घासीदास जयंती है; सुंदरलाल शर्मा जयंती 21 दिसंबर।<br>कथन 3 सही — 10 दिसंबर 1857।"},
    {"q":"अभिकथन (A): रामनामी समाज के लोगों ने अपने शरीर पर राम-नाम गुदवाना आरंभ किया।<br>कारण (R): जातिगत भेदभाव के कारण उन्हें मंदिरों में प्रवेश से रोका जाता था, अतः उन्होंने राम को अपने शरीर पर धारण किया।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही — रामनामी पूरे शरीर पर राम-नाम गुदवाते हैं।<br>R सही और व्याख्या — मंदिर-प्रवेश से वंचित किए जाने के विरोध में \"राम सबके हैं\" का संदेश देने हेतु यह परंपरा चली।"},
    {"q":"अभिकथन (A): बस्तर दशहरे में चार पहियों का फूल रथ और आठ पहियों का विजय रथ अलग-अलग चलाए जाते हैं।<br>कारण (R): मान्यता है कि मूल बारह पहियों वाले रथ को चलाने में कठिनाई होने पर उसे दो रथों में बाँटा गया।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही — फूल रथ (4 पहिए) नवरात्रि में, विजय रथ (8 पहिए) दशमी-एकादशी को।<br>R सही और व्याख्या — 12 पहियों के रथ के 4 + 8 में विभाजन की परंपरा इसी कठिनाई से जोड़ी जाती है।"},
    {"q":"अभिकथन (A): सरहुल उरांव जनजाति का प्रमुख पर्व है।<br>कारण (R): सरहुल कार्तिक माह में धान कटाई के बाद मनाया जाता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही — सरहुल उरांव का प्रमुख प्रकृति-पर्व है।<br>R गलत — सरहुल चैत्र में साल वृक्ष फूलने पर मनाया जाता है।"},
    {"q":"अभिकथन (A): तुरतुरिया में पौष पूर्णिमा पर मेला लगता है।<br>कारण (R): तुरतुरिया को महर्षि वाल्मीकि का आश्रम माना जाता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — पौष पूर्णिमा (छेरछेरा) पर मेला लगता है।<br>R सही — वाल्मीकि आश्रम व लव-कुश जन्म की मान्यता है; पर मेला की तिथि का कारण यह नहीं।"},
    {"q":"अभिकथन (A): खरौद को \"छत्तीसगढ़ की काशी\" कहा जाता है।<br>कारण (R): खरौद महानदी, पैरी और सोंढूर नदियों के संगम पर स्थित है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही — शिव मंदिरों की बहुलता के कारण।<br>R गलत — महानदी-पैरी-सोंढूर संगम राजिम में है।"},
    {"q":"अभिकथन (A): चंपारण पुष्टिमार्गी वैष्णवों का महत्वपूर्ण तीर्थ है।<br>कारण (R): चंपारण महाप्रभु वल्लभाचार्य की प्राकट्य (जन्म) स्थली है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही और R सही — पुष्टिमार्ग के प्रवर्तक की जन्मस्थली होने के कारण ही गुजरात-राजस्थान के वैष्णव यहाँ आते हैं; R, A की व्याख्या है।"},
    {"q":"अभिकथन (A): रायपुर का महंत घासीदास संग्रहालय सतनाम पंथ के प्रवर्तक की स्मृति में बना।<br>कारण (R): महंत घासीदास संग्रहालय की स्थापना 1875 में हुई थी।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":3,"e":"A गलत — संग्रहालय नांदगांव के राजा महंत घासीदास के नाम पर है।<br>R सही — इसकी स्थापना 1875 में हुई।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (पर्व — माह) सही सुमेलित नहीं है?","o":["सरहुल — चैत्र","करमा — भाद्रपद","गोंचा — श्रावण","अक्ती — वैशाख"],"a":2,"e":"गोंचा आषाढ़ शुक्ल द्वितीया को होता है, श्रावण में नहीं। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (मेला-स्थल — जिला) सही सुमेलित नहीं है?","o":["तुरतुरिया — बलौदाबाजार-भाटापारा","पीथमपुर — जांजगीर-चांपा","झलमला — बालोद","कुदुरमाल — कांकेर"],"a":3,"e":"कुदुरमाल कोरबा जिले में हसदेव तट पर है। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (उपनाम — स्थान) सही सुमेलित नहीं है?","o":["छत्तीसगढ़ का प्रयाग — सिरपुर","छत्तीसगढ़ की काशी — खरौद","मिनी तिब्बत — मैनपाट","छत्तीसगढ़ की जगन्नाथपुरी — शिवरीनारायण"],"a":0,"e":"\"छत्तीसगढ़ का प्रयाग\" राजिम (त्रिवेणी संगम) को कहते हैं, सिरपुर को नहीं। शेष युग्म सही हैं।"},
    {"q":"कुनकुरी महागिरजाघर के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. इसे एशिया का दूसरा सबसे बड़ा चर्च माना जाता है।<br>2. यह कोरबा जिले में स्थित है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — एशिया का दूसरा सबसे बड़ा कैथोलिक चर्च।<br>कथन 2 गलत — कुनकुरी जशपुर जिले में है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. गुरु घासीदास का जन्म गिरौदपुरी में हुआ था।<br>2. सतनामी समाज का गुरुद्वारा भंडारपुरी में है।<br>3. गुरु घासीदास की तपोभूमि मैनपाट है।<br>सही कथन हैं —","o":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":0,"e":"कथन 1 सही — गिरौदपुरी जन्मस्थली।<br>कथन 2 सही — भंडारपुरी गुरुद्वारा/गुरु-गद्दी।<br>कथन 3 गलत — तपोभूमि गिरौदपुरी के पास छाता पहाड़ है।"},
    {"q":"सूची-I (देवी-स्थल) को सूची-II (विशेषता) से सुमेलित कीजिए —<br>(A) खल्लारी (B) घुंचापाली (C) अंगारमोती (D) बम्लेश्वरी<br>1. कामकंदला-माधवनल कथा 2. भालुओं का आना 3. भीम-हिडिंबा कथा 4. गंगरेल बाँध के पास पुनर्स्थापित","o":["A-3, B-2, C-1, D-4","A-2, B-3, C-4, D-1","A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1"],"a":3,"e":"खल्लारी — भीम-हिडिंबा।<br>घुंचापाली (चंडी माता) — भालू।<br>अंगारमोती — गंगरेल।<br>बम्लेश्वरी — कामकंदला-माधवनल।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (पर्व — विशेष परंपरा) सही सुमेलित नहीं है?","o":["हरेली — लोहार द्वारा दरवाज़े पर कील","दशहरा — सोनपत्ती भेंट करना","नागपंचमी — कुश्ती","अक्ती — तुलसी विवाह"],"a":3,"e":"तुलसी विवाह जेठौनी (देवउठनी एकादशी) पर होता है; अक्ती पर पुतरा-पुतरी विवाह होता है। शेष युग्म सही हैं।"},
    {"q":"सिरपुर में महानदी तट पर स्थित प्रसिद्ध शिव मंदिर कौन-सा है?","o":["कुलेश्वर महादेव","गंधेश्वर महादेव","हटकेश्वर महादेव","पातालेश्वर महादेव"],"a":1,"e":"सिरपुर (महासमुंद) का गंधेश्वर महादेव मंदिर महानदी तट पर है; कुलेश्वर राजिम में, हटकेश्वर रायपुर में और पातालेश्वर मल्हार में है।"},
    {"q":"पितृ पक्ष (पितरों के श्राद्ध का पखवाड़ा) को छत्तीसगढ़ी में सामान्यतः क्या कहा जाता है?","o":["सुरहुत्ती","पितर पाख","जेठौनी","मातर"],"a":1,"e":"भाद्रपद पूर्णिमा से आश्विन अमावस्या तक \"पितर पाख\" में पूर्वजों को भोग अर्पित किया जाता है; इसके बाद क्वार नवरात्रि आरंभ होती है।"},
    {"q":"छत्तीसगढ़ी लोक-परंपरा में आषाढ़ शुक्ल द्वितीया की रथयात्रा को क्या कहा जाता है?","o":["रथ सप्तमी","रथ पंचमी","रथदूज","रथ एकादशी"],"a":2,"e":"आषाढ़ शुक्ल द्वितीया (दूज) को निकलने के कारण रथयात्रा \"रथदूज\" कहलाती है; बस्तर में यही गोंचा है।"},
    {"q":"गरियाबंद जिले के मरौदा गाँव के पास स्थित, विश्व के सबसे बड़े प्राकृतिक शिवलिंगों में गिना जाने वाला शिवलिंग कौन-सा है?","o":["हटकेश्वरनाथ","कलेश्वरनाथ","लक्ष्मणेश्वर","भूतेश्वरनाथ"],"a":3,"e":"भूतेश्वरनाथ (भकुर्रा महादेव) प्राकृतिक रूप से बढ़ने वाले विशाल शिवलिंग के रूप में प्रसिद्ध है; सावन में यहाँ काँवड़िए आते हैं।"},
    {"q":"जलप्रपात के पास स्थित जतमई माता और घटारानी मंदिर किस जिले में हैं?","o":["गरियाबंद","धमतरी","कांकेर","बालोद"],"a":0,"e":"जतमई और घटारानी दोनों गरियाबंद जिले में हैं और नवरात्रि में यहाँ भीड़ उमड़ती है।"},
    {"q":"कोरबा जिले में पहाड़ी पर स्थित, नवरात्रि मेले के लिए प्रसिद्ध देवी मंदिर कौन-सा है?","o":["बम्लेश्वरी","चंद्रहासिनी","मड़वारानी","खल्लारी"],"a":2,"e":"मड़वारानी मंदिर कोरबा जिले की पहाड़ी पर है; कोरबा की सर्वमंगला देवी भी प्रसिद्ध हैं।"},
    {"q":"बलरामपुर जिले का डीपाडीह किस प्रसिद्ध पुरातात्विक-धार्मिक स्थल के लिए जाना जाता है?","o":["भांड देवल","सामत सरना मंदिर समूह","मामा-भांजा मंदिर","आनंदप्रभु विहार"],"a":1,"e":"डीपाडीह में सामत सरना सहित प्राचीन शिव-शक्ति मंदिरों के अवशेष हैं; भांड देवल आरंग में है।"},
    {"q":"रतनपुर के महामाया मंदिर को शक्तिपीठ मानने के पीछे सती के किस अंग के गिरने की मान्यता है?","o":["दाँत","नेत्र","स्कंध (कंधा)","नाभि"],"a":2,"e":"रतनपुर में सती का स्कंध (कंधा) गिरने की मान्यता है; दंतेवाड़ा में दाँत गिरने की।"},
    {"q":"बस्तर दशहरा की पाट जात्रा के लिए साल की लकड़ी (ठुरलू खोटला) किस गाँव से लाई जाती है?","o":["सरगीपाल","किलेपाल","कुम्हड़ाकोट","बिलौरी"],"a":3,"e":"ठुरलू खोटला बिलौरी गाँव के जंगल से लाया जाता है; बेल पूजा सरगीपाल में होती है।"},
    {"q":"बस्तर दशहरा के प्रथम मुरिया दरबार में मांझी-चालकियों को किस अधिकारी ने संबोधित किया था?","o":["रायपुर के कलेक्टर","सिरोंचा के डिप्टी कमिश्नर","नागपुर के रेज़िडेंट","बस्तर के दीवान"],"a":1,"e":"8 मार्च 1876 को सिरोंचा के डिप्टी कमिश्नर मैकजॉर्ज ने मांझी-चालकियों को संबोधित किया; यहीं से मुरिया दरबार की परंपरा चली।"},
    {"q":"संत गहिरा गुरु का जन्मस्थान \"गहिरा गाँव\" किस जिले में स्थित है?","o":["जशपुर","रायगढ़","सरगुजा","कोरबा"],"a":1,"e":"संत गहिरा गुरु (रामेश्वर गहिरा गुरु) का जन्म रायगढ़ जिले के गहिरा गाँव में हुआ; उनका आश्रम-क्षेत्र जशपुर-सरगुजा तक फैला (कैलाश गुफा, जशपुर)।"},
    {"q":"रामनामी संप्रदाय के अनुयायी मुख्यतः किस नदी के तटीय गाँवों में बसे हैं?","o":["इंद्रावती","हसदेव","महानदी","शिवनाथ"],"a":2,"e":"रामनामी मुख्यतः महानदी तट के जांजगीर-चांपा, सक्ती, रायगढ़, सारंगढ़, बलौदाबाजार अंचलों में हैं; भजन मेला भी इन्हीं गाँवों में बारी-बारी लगता है।"},
    {"q":"भोरमदेव महोत्सव किस जिले में आयोजित होता है?","o":["राजनांदगांव","बेमेतरा","मुंगेली","कबीरधाम"],"a":3,"e":"भोरमदेव मंदिर (1089 ई., फणिनागवंशी गोपालदेव) कबीरधाम जिले में है; यहाँ प्रतिवर्ष भोरमदेव महोत्सव होता है।"},
    {"q":"जगदलपुर के गोंचा पर्व में भगवान को \"तुपकी\" से सलामी देने के लिए किसका प्रयोग किया जाता है?","o":["बाँस की नली और पेंग फल","धनुष-बाण","नगाड़ा","शंख"],"a":0,"e":"बाँस की नली (तुपकी) में पेंग फल भरकर चलाया जाता है — यह गोंचा की अनूठी पहचान है।"},
    {"q":"सिरपुर के लक्ष्मण मंदिर का निर्माण किसने करवाया था?","o":["रानी दुर्गावती","रानी वासटा","रानी फुलकैना","रानी अंबिका देवी"],"a":1,"e":"हर्षगुप्त की पत्नी व महाशिवगुप्त बालार्जुन की माता रानी वासटा ने ईंटों का लक्ष्मण मंदिर बनवाया।"},
    {"q":"बस्तर दशहरा की \"काछन जात्रा\" किस रस्म के बाद संपन्न होती है?","o":["पाट जात्रा","डेरी गड़ाई","बाहर रैनी","जोगी बिठाई"],"a":2,"e":"बाहर रैनी (एकादशी) के बाद काछन जात्रा में काछन देवी के प्रति आभार प्रकट किया जाता है, फिर मुरिया दरबार होता है।"},
    {"q":"छत्तीसगढ़ में \"फरहार\" शब्द किस प्रसंग में प्रयुक्त होता है?","o":["भोजली विसर्जन","गेंड़ी बनाना","नवाखाई का भोग","व्रत तोड़ने का भोजन"],"a":3,"e":"तीजा, कमरछठ आदि व्रतों के बाद लिया जाने वाला भोजन \"फरहार\" कहलाता है।"},
    {"q":"गुरु घासीदास के सात सिद्धांतों में \"पर-स्त्री\" के संबंध में क्या उपदेश है?","o":["पर-स्त्री को माता-बहन मानना","पर-स्त्री से विवाह की अनुमति","स्त्रियों का पंथ में प्रवेश निषेध","स्त्रियों द्वारा जैतखाम पूजा निषेध"],"a":0,"e":"सात सिद्धांतों में व्यभिचार-निषेध है — पर-स्त्री को माता-बहन मानना; पंथ में स्त्री-पुरुष समानता का भाव है।"},
    {"q":"छत्तीसगढ़ के किस पर्व में बहन-बेटियों को ससुराल से मायके लाने की प्रथा सबसे प्रमुख है?","o":["पोला","तीजा","हरेली","छेरछेरा"],"a":1,"e":"तीजा पर भाई अपनी बहनों को मायके लाते हैं; वहीं वे निर्जला व्रत रखती हैं।"},
    {"q":"छत्तीसगढ़ में \"जोत-जंवारा\" किस पर्व की परंपरा है?","o":["दीपावली","होली","नवरात्रि","करमा"],"a":2,"e":"नवरात्रि में ज्योति (जोत) जलाकर जंवारा बोए जाते हैं और नवमी के बाद विसर्जन होता है।"},
    {"q":"स्वामी आत्मानंद द्वारा रायपुर में स्थापित आश्रम कौन-सा है?","o":["दूधाधारी मठ","जैतूसाव मठ","सतनाम आश्रम","विवेकानंद आश्रम"],"a":3,"e":"स्वामी आत्मानंद ने रायपुर में रामकृष्ण-विवेकानंद परंपरा का विवेकानंद आश्रम स्थापित किया।"},
    {"q":"पुष्टिमार्ग के प्रवर्तक वल्लभाचार्य को उनके अनुयायी किस उपाधि से संबोधित करते हैं?","o":["महाप्रभु","जगद्गुरु","संत शिरोमणि","नाम साहब"],"a":0,"e":"वल्लभाचार्य \"महाप्रभु\" कहलाते हैं; \"नाम साहब\" कबीरपंथी वंशगुरुओं की उपाधि है।"},
    {"q":"छत्तीसगढ़ में जैन धर्म का \"श्री उवसग्गहरं पार्श्व तीर्थ\" किस नदी के तट पर है?","o":["खारुन","शिवनाथ","महानदी","हसदेव"],"a":1,"e":"नगपुरा (दुर्ग) का पार्श्व तीर्थ शिवनाथ नदी तट पर है; यहाँ पार्श्वनाथ की प्राचीन प्रतिमा मिली थी।"},
    {"q":"भूतेश्वरनाथ और जतमई के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. भूतेश्वरनाथ गरियाबंद जिले में है।<br>2. जतमई मंदिर जलप्रपात के पास स्थित है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — भूतेश्वरनाथ (मरौदा) गरियाबंद में।<br>कथन 2 सही — जतमई मंदिर के पास ही जलप्रपात बहता है।"},
    {"q":"सूची-I (धार्मिक स्थल) को सूची-II (जिला) से सुमेलित कीजिए —<br>(A) भूतेश्वरनाथ (B) मड़वारानी (C) डीपाडीह (D) नकटा मंदिर<br>1. कोरबा 2. जांजगीर-चांपा 3. गरियाबंद 4. बलरामपुर","o":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4"],"a":0,"e":"भूतेश्वरनाथ — गरियाबंद।<br>मड़वारानी — कोरबा।<br>डीपाडीह — बलरामपुर।<br>नकटा मंदिर — जांजगीर-चांपा।"},
    {"q":"बस्तर दशहरा के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. ठुरलू खोटला सरगीपाल गाँव से लाया जाता है।<br>2. बेल पूजा सरगीपाल गाँव में होती है।<br>3. रथ का निर्माण बेड़ाउमरगाँव और झारउमरगाँव के कारीगर करते हैं।<br>सही कथन हैं —","o":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":1,"e":"कथन 1 गलत — ठुरलू खोटला बिलौरी से आता है।<br>कथन 2 सही — बेल पूजा सरगीपाल में।<br>कथन 3 सही — रथ बेड़ाउमरगाँव-झारउमरगाँव के कारीगर बनाते हैं।"},
    {"q":"अभिकथन (A): पोला के दिन बैलों को सजाकर उनकी पूजा की जाती है।<br>कारण (R): पोला भाद्रपद अमावस्या को मनाया जाता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — पोला बैलों के सम्मान का पर्व है।<br>R सही — तिथि भाद्रपद अमावस्या है; पर तिथि, बैल-पूजा का कारण नहीं है (कारण — खेती में बैलों का योगदान)।"},
    {"q":"अभिकथन (A): आषाढ़ शुक्ल द्वितीया की रथयात्रा को छत्तीसगढ़ में \"रथदूज\" कहते हैं।<br>कारण (R): छत्तीसगढ़ी में द्वितीया तिथि को \"दूज\" कहा जाता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही और R सही — द्वितीया (दूज) को रथ निकलने से ही नाम \"रथदूज\" बना; अतः R, A की व्याख्या है।"},
    {"q":"अभिकथन (A): मैनपाट को \"मिनी तिब्बत\" कहा जाता है।<br>कारण (R): मैनपाट महानदी का उद्गम स्थल है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही — तिब्बती शरणार्थी बस्ती व बौद्ध मठों के कारण।<br>R गलत — महानदी का उद्गम सिहावा (धमतरी) है; मैनपाट से मांड जैसी नदियाँ निकलती हैं।"},
    {"q":"अभिकथन (A): गिरौदपुरी का वार्षिक मेला फाल्गुन शुक्ल पंचमी से सप्तमी तक लगता है।<br>कारण (R): गुरु घासीदास का जन्म 18 दिसंबर को हुआ था।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — मेला फाल्गुन में लगता है।<br>R सही — जन्मतिथि 18 दिसंबर 1756 है; पर मेला जन्मतिथि पर नहीं लगता, अतः R, A की व्याख्या नहीं।"},
    {"q":"अभिकथन (A): दंतेवाड़ा में फाल्गुन माह में फागुन मड़ई लगती है।<br>कारण (R): दंतेश्वरी मंदिर शंखिनी और डंकिनी नदियों के संगम पर है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — दंतेश्वरी की फागुन मड़ई प्रसिद्ध है।<br>R सही — संगम-स्थिति एक अलग भौगोलिक तथ्य है, मड़ई का कारण नहीं।"},
    {"q":"अभिकथन (A): केशकाल की भंगाराम जात्रा में ग्राम देवताओं को भी दंडित किया जा सकता है।<br>कारण (R): भंगाराम देवी को क्षेत्र के देवी-देवताओं की प्रमुख व न्याय करने वाली देवी माना जाता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही — दोषी पाए गए देव को निर्वासन जैसा दंड मिलता है।<br>R सही और व्याख्या — भंगाराम देवी के \"न्यायालय\" की मान्यता के कारण ही यह संभव है।"},
    {"q":"सूची-I (संत/व्यक्तित्व) को सूची-II (जन्मस्थान) से सुमेलित कीजिए —<br>(A) वल्लभाचार्य (B) महर्षि महेश योगी (C) गुरु घासीदास (D) गहिरा गुरु<br>1. पांडुका 2. गिरौदपुरी 3. गहिरा 4. चंपारण","o":["A-4, B-2, C-1, D-3","A-1, B-4, C-2, D-3","A-4, B-1, C-3, D-2","A-4, B-1, C-2, D-3"],"a":3,"e":"वल्लभाचार्य — चंपारण।<br>महेश योगी — पांडुका।<br>गुरु घासीदास — गिरौदपुरी।<br>गहिरा गुरु — गहिरा गाँव।"},
    {"q":"सूची-I (पर्व) को सूची-II (पूज्य देवता) से सुमेलित कीजिए —<br>(A) कमरछठ (B) गौरा-गौरी (C) करमा (D) मातर<br>1. खोड़हर देव 2. बलराम 3. करमसेनी देवी 4. ईसर देव व गौरा","o":["A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-1, D-3"],"a":0,"e":"कमरछठ — बलराम (हलधर)।<br>गौरा-गौरी — ईसर देव (शिव) व गौरा।<br>करमा — करमसेनी देवी।<br>मातर — खोड़हर देव।"},
    {"q":"सूची-I (बस्तर दशहरा की रस्म) को सूची-II (तिथि) से सुमेलित कीजिए —<br>(A) निशा जात्रा (B) मावली परघाव (C) भीतर रैनी (D) कलश स्थापना<br>1. आश्विन शुक्ल प्रतिपदा 2. अष्टमी 3. नवमी 4. दशमी","o":["A-3, B-2, C-4, D-1","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1","A-2, B-3, C-1, D-4"],"a":2,"e":"निशा जात्रा — अष्टमी रात्रि।<br>मावली परघाव — नवमी।<br>भीतर रैनी — दशमी।<br>कलश स्थापना — प्रतिपदा।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (पर्व/मड़ई — स्थान) सही सुमेलित नहीं है?","o":["गोंचा — जगदलपुर","भंगाराम जात्रा — केशकाल","मुरिया दरबार — सिरासार भवन","फागुन मड़ई — कांकेर"],"a":3,"e":"फागुन मड़ई दंतेवाड़ा (माँ दंतेश्वरी) की प्रसिद्ध है। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (प्रवर्तक — पंथ/संस्था) सही सुमेलित नहीं है?","o":["गहिरा गुरु — सनातन धर्म संत समाज","परशुराम भारद्वाज — रामनामी समाज","वल्लभाचार्य — सतनाम पंथ","धनी धर्मदास — धर्मदासी कबीरपंथ"],"a":2,"e":"वल्लभाचार्य पुष्टिमार्ग के प्रवर्तक हैं; सतनाम पंथ गुरु घासीदास का है। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. मड़वा महल का निर्माण<br>2. भोरमदेव मंदिर का निर्माण<br>3. वल्लभाचार्य का जन्म<br>4. सिरपुर में आनंदप्रभु कुटी विहार का निर्माण","o":["4, 2, 1, 3","2, 4, 1, 3","4, 1, 2, 3","4, 2, 3, 1"],"a":0,"e":"आनंदप्रभु विहार (महाशिवगुप्त बालार्जुन, 7वीं सदी) → भोरमदेव (1089) → मड़वा महल (1349) → वल्लभाचार्य जन्म (1479)।"},
    {"q":"श्रावण की हरेली से आरंभ करते हुए निम्नलिखित को घटित होने के क्रम में व्यवस्थित कीजिए —<br>1. नागपंचमी<br>2. आठे कन्हैया<br>3. हरेली<br>4. भोजली विसर्जन","o":["3, 4, 1, 2","3, 1, 2, 4","1, 3, 4, 2","3, 1, 4, 2"],"a":3,"e":"हरेली (श्रावण अमावस्या) → नागपंचमी (श्रावण शुक्ल 5) → भोजली विसर्जन (रक्षाबंधन के अगले दिन) → आठे कन्हैया (भाद्रपद कृष्ण 8)।"},
    {"q":"गोंचा पर्व के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. इसका आयोजन 360 घर आरण्यक ब्राह्मण समाज करता है।<br>2. \"तुपकी\" बाँस की नली से बनती है।<br>3. पर्व का समापन देवशयनी एकादशी पर होता है।<br>सही कथन हैं —","o":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":3,"e":"कथन 1 सही — आयोजक 360 घर आरण्यक ब्राह्मण समाज।<br>कथन 2 सही — बाँस की नली में पेंग फल भरकर चलाते हैं।<br>कथन 3 सही — देवशयनी एकादशी पर समापन।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. माता कर्मा सतनामी समाज की आराध्य हैं।<br>2. माता कर्मा जयंती चैत्र कृष्ण एकादशी को मनाई जाती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — माता कर्मा साहू (तेली) समाज की आराध्य हैं।<br>कथन 2 सही — जयंती चैत्र कृष्ण (पापमोचनी) एकादशी को।"},
    {"q":"तीजा पर्व के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. व्रत की पूर्व संध्या पर करू भात खाया जाता है।<br>2. व्रत अगले दिन फरहार से तोड़ा जाता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — करेले की सब्ज़ी के साथ करू भात।<br>कथन 2 सही — निर्जला व्रत के बाद अगली सुबह फरहार।"},
    {"q":"नवाखाई (नुआखाई) के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. यह पौष पूर्णिमा को मनाया जाता है।<br>2. इसमें नया अन्न पहले इष्टदेव/पूर्वजों को अर्पित किया जाता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — ओड़िशा-सीमावर्ती अंचल में नुआखाई भाद्रपद शुक्ल पंचमी को होता है; पौष पूर्णिमा छेरछेरा है।<br>कथन 2 सही — नया अन्न पहले देवता को अर्पित कर फिर ग्रहण किया जाता है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. गुरु घासीदास विश्वविद्यालय रायपुर में स्थित है।<br>2. संत गहिरा गुरु विश्वविद्यालय अंबिकापुर में स्थित है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — गुरु घासीदास (केंद्रीय) विश्वविद्यालय बिलासपुर में है।<br>कथन 2 सही — पूर्व सरगुजा विश्वविद्यालय अब संत गहिरा गुरु विश्वविद्यालय है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. रायपुर का महादेव घाट हसदेव नदी के तट पर है।<br>2. पीथमपुर के कलेश्वरनाथ में होली के बाद मेला लगता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — महादेव घाट खारुन नदी के तट पर है।<br>कथन 2 सही — धूल पंचमी के आसपास नागा साधुओं की शिव-बारात वाला मेला।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. दामाखेड़ा कोरबा जिले में स्थित है।<br>2. कुदुरमाल बलौदाबाजार-भाटापारा जिले में स्थित है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"कथन 1 गलत — दामाखेड़ा बलौदाबाजार-भाटापारा में है।<br>कथन 2 गलत — कुदुरमाल कोरबा में है। दोनों के जिले उलट दिए गए हैं।"},
    {"q":"रामनामी संप्रदाय के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. इसकी स्थापना संत गहिरा गुरु ने की थी।<br>2. इसका बड़े भजन मेला माघ पूर्णिमा को लगता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"कथन 1 गलत — संस्थापक परशुराम भारद्वाज हैं।<br>कथन 2 गलत — बड़े भजन मेला पौष शुक्ल एकादशी से त्रयोदशी तक लगता है।"},
    {"q":"धर्मदासी कबीरपंथ के वंशगुरुओं (आचार्यों) के नाम के अंत में कौन-सी उपाधि लगती है?","o":["दास","महाप्रभु","गुरु","नाम साहब"],"a":3,"e":"मुक्तामणि नाम साहब से आरंभ होकर सभी वंशगुरु \"नाम साहब\" कहलाते हैं; \"महाप्रभु\" वल्लभाचार्य की उपाधि है।"},
    {"q":"गिरौदपुरी के पास गुरु घासीदास से जुड़ा कौन-सा पवित्र जलकुंड है?","o":["लक्ष्मण कुंड","सीता कुंड","राम कुंड","चरण कुंड"],"a":3,"e":"गिरौदपुरी क्षेत्र में चरण कुंड और अमृत कुंड गुरु घासीदास की स्मृति से जुड़े हैं।"},
    {"q":"बस्तर के दियारी पर्व में गाय-बैलों को परंपरागत रूप से क्या खिलाया जाता है?","o":["पसहर चावल","करू भात","खिचड़ी","ठेठरी"],"a":2,"e":"दियारी (बस्तर का दीपावली-रूप) में पशुधन की पूजा कर उन्हें खिचड़ी खिलाई जाती है; मैदानी क्षेत्र में गोवर्धन पूजा पर भी यही परंपरा है।"},
    {"q":"सिरपुर का लक्ष्मण मंदिर मुख्यतः किस सामग्री से निर्मित है?","o":["बलुआ पत्थर","संगमरमर","ग्रेनाइट","पकी ईंटें"],"a":3,"e":"सिरपुर का लक्ष्मण मंदिर भारत के श्रेष्ठ ईंट-निर्मित मंदिरों में गिना जाता है; इसे रानी वासटा ने बनवाया।"},
    {"q":"बस्तर के माटी तिहार के दिन कौन-सा कार्य परंपरागत रूप से वर्जित रहता है?","o":["तालाब में स्नान","देवी-देवताओं की पूजा","भूमि खोदना/जोतना","नए वस्त्र पहनना"],"a":2,"e":"माटी तिहार में धरती माता की पूजा होती है; इस दिन भूमि खोदना वर्जित है ताकि धरती को \"विश्राम\" मिले।"},
    {"q":"अगहन माह में स्त्रियों द्वारा लक्ष्मी पूजा का व्रत सप्ताह के किस दिन किया जाता है?","o":["सोमवार","गुरुवार","शुक्रवार","रविवार"],"a":1,"e":"\"बिरस्पत\" = बृहस्पतिवार (गुरुवार); अगहन के हर गुरुवार घर लीपकर चौक बनाकर लक्ष्मी पूजा होती है।"},
    {"q":"जगदलपुर का माँ दंतेश्वरी मंदिर किस परिसर में स्थित है?","o":["सिरासार भवन","राजमहल परिसर","कुम्हड़ाकोट","निशागुड़ी"],"a":1,"e":"जगदलपुर में दंतेश्वरी मंदिर राजमहल परिसर में है; पाट जात्रा इसी मंदिर के सामने होती है।"},
    {"q":"बस्तर दशहरा के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. काछन गादी की रस्म कार्तिक अमावस्या को होती है।<br>2. जोगी बिठाई में पनका जाति का व्यक्ति बैठता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"कथन 1 गलत — काछन गादी आश्विन अमावस्या को होती है।<br>कथन 2 गलत — जोगी हल्बा जाति का होता है; पनका जाति की कन्या काछन देवी बनती है।"},
    {"q":"सूची-I (पर्व) को सूची-II (मुख्य परंपरा) से सुमेलित कीजिए —<br>(A) सुरहुत्ती (B) जेठौनी (C) अगहन बिरस्पत (D) पूस पुन्नी<br>1. छेरछेरा (अन्नदान) 2. लक्ष्मी पूजा व गौरा-गौरी 3. तुलसी विवाह 4. गुरुवार का लक्ष्मी व्रत","o":["A-3, B-2, C-4, D-1","A-2, B-3, C-4, D-1","A-2, B-3, C-1, D-4","A-2, B-4, C-3, D-1"],"a":1,"e":"सुरहुत्ती — लक्ष्मी पूजा, गौरा-गौरी।<br>जेठौनी — तुलसी विवाह।<br>अगहन बिरस्पत — गुरुवार का व्रत।<br>पूस पुन्नी — छेरछेरा।"},
    {"q":"अभिकथन (A): छेरछेरा पर्व कार्तिक पूर्णिमा को मनाया जाता है।<br>कारण (R): छेरछेरा पर किसान अपनी नई फसल में से अन्नदान करते हैं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":3,"e":"A गलत — छेरछेरा पौष पूर्णिमा को होता है, जब धान घर आ चुका होता है।<br>R सही — यह अन्नदान का पर्व है।"},
    {"q":"अभिकथन (A): रतनपुर के महामाया मंदिर में नवरात्रि पर हज़ारों ज्योति कलश जलाए जाते हैं।<br>कारण (R): रतनपुर कलचुरि राजवंश की राजधानी रहा था।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — मनोकामना ज्योति कलश की परंपरा प्रसिद्ध है।<br>R सही — रतनपुर कलचुरियों की राजधानी था; पर यह ज्योति कलश परंपरा का कारण नहीं, आस्था इसका आधार है।"},
    {"q":"मातर पर्व के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. मातर मुख्यतः गोंड समाज का पर्व है।<br>2. मातर में खोड़हर देव की पूजा की जाती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — मातर राउत (यादव) समाज का पर्व है।<br>कथन 2 सही — दईहान में खोड़हर देव की स्थापना कर पूजा होती है।"}
  ]
});
